//! Source Drop protocol selection and reference-receiver contracts.
#[path = "support/execution.rs"]
mod finite_default_support;
#[test]
fn cleanup_access_export_retains_parameter_and_indirect_origins() {
    use elaboration::verification::{memory, moves};
    let package = compile(
        "trait Duplicate {} trait Retire {fn drop(*self);}
        struct Watch {target:*bool}impl Retire for Watch {fn drop(*self) {self.target.*.* = true;}}
        fn direct(p:*bool) {let watch=Watch {target:p};}
        fn indirect(p:**bool) {let target=p.*;let watch=Watch {target:target};}
        fn loop_indirect(p:**bool) {var again=true;while again {let target=p.*;let watch=Watch {target:target};again=false;}}
        fn loop_direct(p:*bool) {var again=true;while again {let watch=Watch {target:p};again=false;}}
        fn loop_call(p:*bool) {let set=|q:*bool| {let watch=Watch {target:q};};var again=true;while again {set(p);again=false;}}
        fn loop_indirect_call(p:**bool) {let set=|q:*bool| {let watch=Watch {target:q};};var again=true;while again {let target=p.*;set(target);again=false;}}
        fn nested_loop_indirect(p:**bool) {var again=true;while again {var inner=true;while inner {let target=p.*;let watch=Watch {target:target};inner=false;}again=false;}}
        struct Link {ready:bool,target:*bool}
        fn field(link:Link) {let watch=Watch {target:link.target};}
        fn local_only() {let flag=false;let watch=Watch {target:flag.ref};}",
    );
    world(&package, |world, items| {
        let mut items = items.clone();
        let copy = package
            .traits
            .iter()
            .find(|t| t.name == "Duplicate")
            .unwrap()
            .declaration;
        items
            .bind_source_traits(&package, &[(LangItem::Copy, copy)])
            .unwrap();
        for (name, indirect) in [
            ("direct", false),
            ("indirect", true),
            ("loop_direct", false),
            ("loop_indirect", true),
            ("nested_loop_indirect", true),
            ("loop_call", false),
            ("loop_indirect_call", true),
            ("local_only", false),
            ("field", false),
        ] {
            let function = package.functions.iter().find(|f| f.name == name).unwrap();
            let subject = if indirect {
                nir::Term::Pointer(Box::new(nir::Term::Primitive(nir::Primitive::Bool)))
            } else {
                nir::Term::Primitive(nir::Primitive::Bool)
            };
            let borrows = if name == "local_only" || name == "field" {
                vec![]
            } else {
                vec![(0, subject)]
            };
            let fields = if name == "field" {
                vec![moves::BorrowedField {
                    parameter: 0,
                    fields: vec![1],
                    pointee: nir::Term::Primitive(nir::Primitive::Bool),
                }]
            } else {
                vec![]
            };
            let mut report = luna::protocols::analyze_cleanup_with_field_context(
                &package,
                world,
                &items,
                function,
                100_000,
                Default::default(),
                &borrows,
                &[],
                &[],
                vec![],
                &fields,
            )
            .unwrap();
            let effects = report
                .cleanup_memory_accesses(&package, &mut 10000)
                .unwrap();
            if name == "local_only" {
                assert!(effects.is_empty());
                continue;
            }
            assert_eq!(
                effects,
                vec![memory::Access {
                    target: memory::ParameterPlace {
                        parameter: 0,
                        input_fields: if name == "field" { vec![1] } else { vec![] },
                        through: if indirect { vec![vec![]] } else { vec![] },
                        conditions: Default::default(),
                        fields: vec![]
                    },
                    write: true,
                    read_value: true,
                    ty: nir::Term::Primitive(nir::Primitive::Bool),
                }],
                "{name}: {report}"
            );
            assert!(
                report
                    .to_string()
                    .contains("(borrowed-roots (borrowed-root")
            );
            assert!(report.cleanup_memory_accesses(&package, &mut 0).is_err());
            assert_eq!(
                report
                    .cleanup_memory_accesses(&package, &mut 10000)
                    .unwrap(),
                effects
            );
            report.borrowed_roots.clear();
            assert!(
                report
                    .cleanup_memory_accesses(&package, &mut 10000)
                    .unwrap_err()
                    .contains("enclosing invocation context")
            );
        }
    });
}

#[test]
fn scheduled_computed_code_patterns_evaluate_each_attempt_once() {
    use comptime_interpretor::{Interpreter, Value};
    let package=compile("trait Duplicate {} trait Retire {fn drop(*self);}
        typealias Action=fn(bool)->bool;impl Duplicate for Action {}
        fn invert(value:bool)->bool {not value}
        fn produce()->Action {invert}
        fn forward(action:Action)->Action {action}
        fn unchanged(value:bool)->bool {value}
        fn choose(flag:bool)->bool {
            let action=if flag {invert} else {unchanged};
            false match {_ if action(false)=>true,_=>true}
        }
        fn both()->bool {choose(true) and choose(false)}
        fn single()->bool {false match {_ and produce() is action=>action(false)}}
        fn nested()->bool {false match {_ and forward(produce()) is action=>action(false)}}
        fn guarded()->bool {false match {_ and produce() is action if action(false)=>action(false),_=>false}}
        fn factory_guard()->bool {false match {_ if produce()(false)=>true,_=>false}}
        fn block_guard()->bool {false match {_ if (do {let action=produce();action})(false)=>true,_=>false}}
        fn conditional_guard()->bool {false match {_ if (if true {produce()} else {unchanged})(false)=>true,_=>false}}
        fn apply(action:Action)->bool {action(false)}
        fn argument_guard()->bool {false match {_ if apply(produce())=>true,_=>false}}
        fn match_guard()->bool {false match {_ if (true match {true=>produce(),false=>unchanged})(false)=>true,_=>false}}
        fn match_binding()->bool {false match {_ and (produce() match {action=>forward(action)}) is next=>next(false)}}
        fn match_retry()->bool {false match {_ and (false match {
            _ and produce() is action if false=>action,
            _=>produce()
        }) is next=>next(false)}}
        fn match_select(flag:bool)->bool {false match {_ if (flag match {true=>produce(),false=>unchanged})(false)=>true,_=>false}}
        fn match_both()->bool {match_select(true) and not match_select(false)}
        fn local_pattern()->bool {false match {_ and do {
            let _ and produce() is action=false;
            forward(action)
        } is next=>next(false)}}
        fn local_pattern_guard()->bool {false match {_ if do {
            let first and forward(first) is action=produce();
            action(false)
        }=>true,_=>false}}
        fn failed_let()->bool {
            let _ and do {var action=invert;action=forward(produce());action} is next if false=false else {return true;};
            next(false)
        }
        fn default_value(value:bool)->bool {not value}
        fn with_default(value:bool,.selected:bool=default_value(value))->bool {selected}
        fn default_guard()->bool {false match {_ if with_default(false)=>true,_=>false}}
        fn override_guard()->bool {false match {_ if with_default(true,.selected=true)=>true,_=>false}}
        fn default_chain(value:bool,.second:bool=default_value(value),.third:bool=default_value(second))->bool {third}
        fn chain_guard()->bool {false match {_ if default_chain(true)=>true,_=>false}}
        fn chain_override()->bool {false match {_ if default_chain(false,.second=false)=>true,_=>false}}
        fn reassigned()->bool {false match {
            _ and do {var local=invert;local=forward(produce());local} is action if false=>action(false),
            _ and do {var local=invert;local=forward(produce());local} is action=>action(false)
        }}
        fn retry()->bool {false match {
            _ and produce() is action if false=>action(false),
            _ and produce() is action=>action(false)
        }}");
    for (entry, expected) in [
        ("single", vec!["single", "produce", "invert"]),
        ("nested", vec!["nested", "produce", "forward", "invert"]),
        ("guarded", vec!["guarded", "produce", "invert", "invert"]),
        ("factory_guard", vec!["factory_guard", "produce", "invert"]),
        ("block_guard", vec!["block_guard", "produce", "invert"]),
        (
            "conditional_guard",
            vec!["conditional_guard", "produce", "invert"],
        ),
        (
            "argument_guard",
            vec!["argument_guard", "produce", "apply", "invert"],
        ),
        ("match_guard", vec!["match_guard", "produce", "invert"]),
        (
            "match_binding",
            vec!["match_binding", "produce", "forward", "invert"],
        ),
        (
            "match_retry",
            vec!["match_retry", "produce", "produce", "invert"],
        ),
        (
            "match_both",
            vec![
                "match_both",
                "match_select",
                "produce",
                "invert",
                "match_select",
                "unchanged",
            ],
        ),
        (
            "local_pattern",
            vec!["local_pattern", "produce", "forward", "invert"],
        ),
        (
            "local_pattern_guard",
            vec!["local_pattern_guard", "produce", "forward", "invert"],
        ),
        ("failed_let", vec!["failed_let", "produce", "forward"]),
        (
            "default_guard",
            vec!["default_guard", "default_value", "with_default"],
        ),
        ("override_guard", vec!["override_guard", "with_default"]),
        (
            "chain_guard",
            vec![
                "chain_guard",
                "default_value",
                "default_value",
                "default_chain",
            ],
        ),
        (
            "chain_override",
            vec!["chain_override", "default_value", "default_chain"],
        ),
        (
            "both",
            vec!["both", "choose", "invert", "choose", "unchanged"],
        ),
        (
            "reassigned",
            vec![
                "reassigned",
                "produce",
                "forward",
                "produce",
                "forward",
                "invert",
            ],
        ),
        ("retry", vec!["retry", "produce", "produce", "invert"]),
    ] {
        let executable = source_executable(&package, entry).unwrap();
        let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
            .unwrap()
            .with_cleanup_schedule(&executable.schedule)
            .unwrap();
        assert_eq!(
            vm.invoke_instance(&executable.entry, vec![]).unwrap(),
            Value::Bool(true)
        );
        assert_eq!(executed_names(&package, &executable, vm.events()), expected);
    }
}

#[test]
fn later_record_pattern_mismatch_preserves_earlier_computations() {
    use comptime_interpretor::{Interpreter, Value};
    for (ty, right, pattern) in [("bool", "true", "false"), ("Choice", "Choice.yes", ".no")] {
        for bound in [false, true] {
            let value = format!("Pair {{left:true,right:{right}}}");
            let prefix = if bound {
                format!("let pair={value};")
            } else {
                String::new()
            };
            let subject = if bound { "pair" } else { value.as_str() };
            let package = compile(&format!(
                "trait Duplicate {{}} trait Retire {{fn drop(*self);}}
                enum Choice {{yes,no}} struct Pair {{left:bool,right:{ty}}}
                fn mark()->bool {{true}}
                fn entry()->bool {{{prefix}{subject} match {{
                    {{left:_ and mark() is _,right:{pattern}}}=>false,_=>true
                }}}}"
            ));
            let executable = source_executable(&package, "entry").unwrap();
            let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_cleanup_schedule(&executable.schedule)
                .unwrap();
            assert_eq!(
                vm.invoke_instance(&executable.entry, vec![]).unwrap(),
                Value::Bool(true)
            );
            assert_eq!(
                executed_names(&package, &executable, vm.events()),
                vec!["entry", "mark"],
                "{ty}/{bound}"
            );
        }
    }
}

#[test]
fn computed_code_patterns_do_not_admit_rejecting_guards_without_failure_transfer() {
    let package = compile(
        "trait Duplicate {} trait Retire {fn drop(*self);}
        typealias Action=fn(bool)->bool;impl Duplicate for Action {}
        fn invert(value:bool)->bool {not value}
        fn reject(action:Action)->bool {assumes false;action(false)}
        fn entry()->bool {false match {_ and invert is action if reject(action)=>true,_=>false}}",
    );
    let error = source_executable(&package, "entry").unwrap_err();
    assert!(error.contains("failure-path"), "{error}");
}

#[test]
fn indirect_guard_calls_require_every_target_to_have_observation_evidence() {
    for body in [
        "let action=unknown;false match {_ if action(false)=>true,_=>false}",
        "let action=if flag {invert} else {reject};false match {_ if action(false)=>true,_=>false}",
        "let action=if flag {reject} else {invert};false match {_ if action(false)=>true,_=>false}",
        "false match {_ if bad_factory()(false)=>true,_=>false}",
        "false match {_ if (do {let action=unknown;action})(false)=>true,_=>false}",
        "false match {_ if (if flag {invert} else {unknown})(false)=>true,_=>false}",
        "false match {_ if rejecting_factory()(false)=>true,_=>false}",
        "false match {_ if apply(bad_factory())=>true,_=>false}",
        "false match {_ if (flag match {true=>invert,false=>unknown})(false)=>true,_=>false}",
        "false match {_ if (flag match {true=>invert,false=>reject})(false)=>true,_=>false}",
        "false match {_ if (do {let _ and unknown is action=false;action})(false)=>true,_=>false}",
        "false match {_ if reject_default(false)=>true,_=>false}",
    ] {
        let source = format!(
            "trait Duplicate {{}} trait Retire {{fn drop(*self);}}
            typealias Action=fn(bool)->bool;impl Duplicate for Action {{}}
            fn invert(value:bool)->bool {{not value}}
            fn reject(value:bool)->bool {{assumes false;value}}
            fn bad_factory()->Action {{reject}}
            fn rejecting_factory()->Action {{assumes false;invert}}
            fn apply(action:Action)->bool {{action(false)}}
            fn reject_default(value:bool,.allowed:bool=false)->bool {{assumes allowed;value}}
            fn entry(flag:bool,unknown:Action)->bool {{{body}}}"
        );
        let package = compile(&source);
        let error = cleanup_report(&package, "entry").unwrap_err().to_string();
        assert!(
            error.contains("guard") && error.contains("failure-path"),
            "{body}: {error}"
        );
    }
}

#[test]
fn observed_matches_do_not_hide_branch_side_effects() {
    for body in [
        "var state=false;false match {_ if (flag match {true=>do {state=true;true},false=>false})=>true,_=>false}",
        "false match {_ if (flag match {true=>do {assumes false;true},false=>false})=>true,_=>false}",
        "false match {_ if (flag match {true=>do {return true;},false=>false})=>true,_=>false}",
        "var state=false;false match {_ if do {let _ and do {state=true;true} is result=false;result}=>true,_=>false}",
        "false match {_ if do {let true=flag else {return true;};true}=>true,_=>false}",
    ] {
        let source = format!(
            "trait Duplicate {{}} trait Retire {{fn drop(*self);}}
            fn entry(flag:bool)->bool {{{body}}}"
        );
        let package = compile(&source);
        let error = cleanup_report(&package, "entry").unwrap_err().to_string();
        assert!(error.contains("failure-path"), "{body}: {error}");
    }
}

#[test]
fn guard_defaults_cannot_read_a_later_unprepared_parameter() {
    let mut package = compile(
        "trait Duplicate {} trait Retire {fn drop(*self);}
        fn choose(value:bool,.second:bool=not value,.third:bool=not second)->bool {third}
        fn entry()->bool {false match {_ if choose(true)=>true,_=>false}}",
    );
    let target = package
        .functions
        .iter()
        .find(|f| f.name == "choose")
        .unwrap()
        .declaration;
    let entry = package
        .functions
        .iter_mut()
        .find(|f| f.name == "entry")
        .unwrap();
    let mut changed = false;
    nir::visit::expression_mut(&mut entry.body, &mut 100000, |expr, _| {
        if let nir::program::ExprKind::Call {
            callee,
            arguments,
            parameter_bindings,
        } = &mut expr.kind
        {
            if matches!(callee.kind,nir::program::ExprKind::Function(id) if id==target) {
                let default = arguments
                    .iter_mut()
                    .find(|arg| arg.is_default && arg.parameter == 1)
                    .unwrap();
                default.value.kind = nir::program::ExprKind::Local(parameter_bindings[2]);
                changed = true;
            }
        }
        Ok(())
    })
    .unwrap();
    assert!(changed);
    let error = cleanup_report(&package, "entry").unwrap_err().to_string();
    assert!(error.contains("unavailable"), "{error}");
}

#[test]
fn scheduled_discarded_assignment_retires_projected_callee_once_per_iteration() {
    use comptime_interpretor::{Interpreter, Value};
    let package = compile(
        "trait Duplicate {} trait Retire {fn drop(*self);}
        struct Held {} impl Retire for Held {fn drop(*self) {}}
        typealias Callback=%{held:Held} fn()->bool;
        struct Ops {action:Callback}
        fn make()->Ops {let held=Held {};Ops {action:|| do {let observed=held;true}}}
        fn entry()->bool {
            var remaining:.u8'builtin=2;var result=false;
            while remaining > 0 {let ops=make();result=ops.action();remaining -= 1;}
            result
        }",
    );
    let executable = source_executable(&package, "entry").unwrap();
    let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
        .unwrap()
        .with_cleanup_schedule(&executable.schedule)
        .unwrap();
    assert_eq!(
        vm.invoke_instance(&executable.entry, vec![]).unwrap(),
        Value::Bool(true)
    );
    assert_eq!(
        executed_names(&package, &executable, vm.events()),
        ["entry", "make", "drop Held", "make", "drop Held"]
    );
}

