fn scalar_call_pattern_guards_reject_transfer_and_contract_failure() {
    for (definition, call) in [
        ("fn accept(item:Held)->bool {true}", "accept(item)"),
        (
            "fn accept(flag:bool)->bool {assumes flag;flag}",
            "accept(flag)",
        ),
    ] {
        let package = compile(&format!(
            "trait Duplicate {{}} trait Retire {{fn drop(*self);}}
            struct Held {{}} impl Retire for Held {{fn drop(*self) {{}}}}
            {definition}
            fn entry(flag:bool) {{Held {{}} match {{item if {call}=>(),_=>()}};}}"
        ));
        let error = source_executable(&package, "entry")
            .err()
            .expect("moved enum must be rejected");
        assert!(
            error.contains("guard") && error.contains("failure-path"),
            "{error}"
        );
    }
}

