#[test]
fn candidate_order_patterns_calls_restore_caller_receipts_and_validate_metadata() {
    use comptime_interpretor::{Interpreter, Value};
    let package=compile("trait Duplicate {} trait Retire {fn drop(*self);}
        struct Held {tag:bool} impl Retire for Held {fn drop(*self) {if self.tag.* {left();} else {right();}}}
        fn left() {} fn right() {}
        fn nested(flag:bool) {let ((true,first,second) or (false,second,first))=(flag,Held {tag:true},Held {tag:false});}
        fn entry() {let ((true,first,second) or (false,second,first))=(false,Held {tag:true},Held {tag:false});
            nested(true);nested(false);
        }");
    let executable = source_executable(&package, "entry").unwrap();
    let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
        .unwrap()
        .with_cleanup_schedule(&executable.schedule)
        .unwrap();
    assert_eq!(
        vm.invoke_instance(&executable.entry, vec![]).unwrap(),
        Value::Unit
    );
    assert_eq!(
        executed_names(&package, &executable, vm.events()),
        [
            "entry",
            "nested",
            "drop Held",
            "right",
            "drop Held",
            "left",
            "nested",
            "drop Held",
            "right",
            "drop Held",
            "left",
            "drop Held",
            "right",
            "drop Held",
            "left"
        ]
    );
    for defect in 0..4 {
        let mut schedule = executable.schedule.clone();
        let function = schedule
            .functions
            .iter_mut()
            .find(|function| !function.pattern_orders.is_empty())
            .unwrap();
        match defect {
            0 => {
                function.pattern_orders[0].alternatives[1] =
                    function.pattern_orders[0].alternatives[0].clone()
            }
            1 => {
                function.pattern_orders[0].alternatives[1].pop();
            }
            2 => {
                let binding = function.pattern_orders[0].alternatives[0][0];
                function.pattern_orders[0].alternatives[0].push(binding);
            }
            3 => function
                .pattern_orders
                .push(function.pattern_orders[0].clone()),
            _ => unreachable!(),
        }
        assert!(
            Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_cleanup_schedule(&schedule)
                .is_err(),
            "defect {defect}"
        );
    }
}

