#[test]
fn scheduled_owned_defaults_observe_pointer_inputs_and_cleanup_once() {
    use comptime_interpretor::{ErrorKind, Interpreter, Value};
    for default in ["do {Item {flag:pointer.*}}", "make(pointer)"] {
        let package = compile(&format!(
            "trait Retire {{fn drop(*self);}} trait Duplicate {{}}
             struct Item {{flag:bool,}} struct Caller {{}}
             impl Retire for Item {{fn drop(*self) {{}}}}
             impl Retire for Caller {{fn drop(*self) {{}}}}
             fn make(pointer:*bool)->Item {{Item {{flag:pointer.*}}}}
             fn target(pointer:*bool,.item:Item={default})->bool {{assumes item.flag;item.flag}}
             fn entry(flag:bool)->bool {{let caller=Caller {{}};target(flag.ref)}}"
        ));
        let executable = source_executable(&package, "entry").unwrap();
        for flag in [true, false] {
            let mut interpreter = Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_cleanup_schedule(&executable.schedule)
                .unwrap();
            let result = interpreter.invoke_instance(&executable.entry, vec![Value::Bool(flag)]);
            if flag {
                assert_eq!(result.unwrap(), Value::Bool(true));
            } else {
                assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
            }
            let expected = if default == "make(pointer)" {
                vec!["entry", "make", "target", "drop Item", "drop Caller"]
            } else {
                vec!["entry", "target", "drop Item", "drop Caller"]
            };
            assert_eq!(
                executed_names(&package, &executable, interpreter.events()),
                expected
            );
        }
    }
}

