#[test]
fn constructor_spreads_preserve_projected_owner_lifetimes_and_failure_cleanup() {
    use comptime_interpretor::{ErrorKind, Interpreter};
    for rejected in [false, true] {
        let mut traces = Vec::new();
        for spread in [false, true] {
            let tail = if rejected {
                "do {assumes false;Right {}}"
            } else {
                "Right {}"
            };
            let input = if spread {
                format!("Choice.pair(...do {{(make().first,)}},...do {{({tail},)}})")
            } else {
                format!("Choice.pair(make().first,{tail})")
            };
            let package = compile(&format!(
                "trait Retire {{fn drop(*self);}} trait Duplicate {{}} struct Left {{}} struct Right {{}} struct Extra {{}} struct Pair {{first:Left,extra:Extra}} enum Choice {{pair(Left,Right)}} impl Retire for Left {{fn drop(*self) {{}}}} impl Retire for Right {{fn drop(*self) {{}}}} impl Retire for Extra {{fn drop(*self) {{}}}} fn make()->Pair {{Pair {{first:Left {{}},extra:Extra {{}}}}}} fn entry() {{let result={input};}}"
            ));
            let executable = source_executable(&package, "entry").unwrap();
            let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_cleanup_schedule(&executable.schedule)
                .unwrap();
            let result = vm.invoke_instance(&executable.entry, vec![]);
            if rejected {
                assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
            } else {
                assert!(result.is_ok(), "{result:?}");
            }
            traces.push(executed_names(&package, &executable, vm.events()));
        }
        // A source do-block has its own temporary boundary, so compare actual
        // retirement counts rather than equating it to a direct projection.
        for trace in traces {
            assert_eq!(
                trace
                    .iter()
                    .filter(|name| name.as_str() == "drop Left")
                    .count(),
                1,
                "{trace:?}"
            );
            assert_eq!(
                trace
                    .iter()
                    .filter(|name| name.as_str() == "drop Extra")
                    .count(),
                1,
                "{trace:?}"
            );
            assert_eq!(
                trace
                    .iter()
                    .filter(|name| name.as_str() == "drop Right")
                    .count(),
                usize::from(!rejected),
                "{trace:?}"
            );
        }
    }
}

