#[test]
fn record_cleanup_plans_nested_fields_and_skips_transferred_responsibilities() {
    use elaboration::verification::{
        PlaceId,
        drop::{CleanupStep, plan_cleanup},
        ownership::{Place, Shape, State},
    };
    let package = compile(
        "trait Retire {fn drop(*self);} struct Left {} struct Right {} impl Retire for Left {fn drop(*self) {}} impl Retire for Right {fn drop(*self) {}}",
    );
    world(&package, |world, items| {
        let ty = nir::Term::Record(vec![
            ("left".into(), nominal(&package, "Left", vec![])),
            (
                "nested".into(),
                nir::Term::Record(vec![("right".into(), nominal(&package, "Right", vec![]))]),
            ),
        ]);
        let acquired = luna::protocols::acquire_cleanup(
            &package,
            world,
            items,
            &ty,
            Budget::default(),
            &mut 10000,
        )
        .unwrap();
        let root = PlaceId { owner: 1, local: 1 };
        let receiver = Place {
            root,
            fields: vec![],
        };
        let mut state = State::default();
        state
            .declare(
                root,
                &Shape::Fields(vec![
                    Shape::Fields(vec![]),
                    Shape::Fields(vec![Shape::Fields(vec![])]),
                ]),
                true,
                &mut 1000,
            )
            .unwrap();
        for expected in [vec![vec![1, 0], vec![0]], vec![vec![0]]] {
            let before = state.clone();
            let plan =
                plan_cleanup(&package, world, &acquired, &state, &receiver, &mut 10000).unwrap();
            let paths: Vec<_> = plan
                .steps
                .iter()
                .filter_map(|s| {
                    if let CleanupStep::Invoke { access, .. } = s {
                        Some(access.receiver.fields.clone())
                    } else {
                        None
                    }
                })
                .collect();
            assert_eq!(paths, expected, "{plan}");
            assert_eq!(
                state, before,
                "planning must not retire resources before execution"
            );
            if expected.len() == 2 {
                state
                    .take(&Place {
                        root,
                        fields: vec![1, 0],
                    })
                    .unwrap();
            }
        }
    });
}

#[test]
fn record_ir_executes_acquired_cleanup_for_complete_and_partial_construction() {
    use comptime_interpretor::{Interpreter, Value};
    use nir::program::ExprKind as K;
    for (tail, expected) in [
        ("Right {}", vec!["entry", "drop Right", "drop Left"]),
        ("do {return;Right {}}", vec!["entry", "drop Left"]),
    ] {
        let mut package = compile(&format!(
            "trait Retire {{fn drop(*self);}} trait Duplicate {{}} struct Left {{}} struct Right {{}} struct Bundle {{first:Left,second:Right}} impl Retire for Left {{fn drop(*self) {{}}}} impl Retire for Right {{fn drop(*self) {{}}}} fn entry() {{let value=Bundle {{first:Left {{}},second:{tail}}};}}"
        ));
        let record = nir::Term::Record(vec![
            ("first".into(), nominal(&package, "Left", vec![])),
            ("second".into(), nominal(&package, "Right", vec![])),
        ]);
        let entry = package
            .functions
            .iter_mut()
            .find(|f| f.name == "entry")
            .unwrap();
        let K::Block { statements, .. } = &mut entry.body.kind else {
            panic!("block")
        };
        let K::Let { value, .. } = &mut statements[0].kind else {
            panic!("binding")
        };
        let K::Record { fields, .. } = std::mem::replace(&mut value.kind, K::Unit) else {
            panic!("construction")
        };
        value.kind = K::AnonymousRecord { fields };
        if value.ty != nir::Term::Primitive(nir::Primitive::Never) {
            value.ty = record;
        }
        // This is an IR fixture until source attribute collection is connected.
        nir::phases::validate(&package).unwrap();
        let executable = source_executable(&package, "entry").unwrap();
        let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
            .unwrap()
            .with_cleanup_schedule(&executable.schedule)
            .unwrap();
        assert_eq!(
            vm.invoke_instance(&executable.entry, vec![]).unwrap(),
            Value::Unit
        );
        assert_eq!(
            executed_names(&package, &executable, vm.events()),
            expected,
            "{tail}"
        );
    }
}

