#[test]
fn aggregate_callback_arguments_retire_once_on_success_and_rejection() {
    use comptime_interpretor::{ErrorKind, Interpreter, Value};
    for (action, rejected) in [("negate", false), ("identity", true)] {
        let package = compile(&format!(
            "trait Retire {{fn drop(*self);}} trait Duplicate {{}} struct Operations {{action:fn(bool)->bool}} impl Retire for Operations {{fn drop(*self) {{}}}} fn negate(value:bool)->bool {{not value}} fn identity(value:bool)->bool {{value}} fn apply(ops:Operations) {{let result=ops.action(false);assumes result;}} fn entry() {{apply(Operations {{action:{action}}});}}"
        ));
        let executable = source_executable(&package, "entry").unwrap();
        let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
            .unwrap()
            .with_cleanup_schedule(&executable.schedule)
            .unwrap();
        let result = vm.invoke_instance(&executable.entry, vec![]);
        if rejected {
            assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
        } else {
            assert_eq!(result.unwrap(), Value::Unit);
        }
        assert_eq!(
            executed_names(&package, &executable, vm.events()),
            ["entry", "apply", action, "drop Operations"]
        );
    }
}

