#[test]
fn computed_capture_initializers_preserve_evaluated_callable_evidence() {
    use comptime_interpretor::{Interpreter, Value};
    use nir::program::{Expr, ExprKind as K};
    for (declarations, body) in [
        (
            "fn factory()->fn(fn(bool)->bool,bool)->bool {apply}",
            "let helper:fn(fn(bool)->bool,bool)->bool=other_apply;let callback=|| helper(negate,false);let result=callback();assumes result;",
        ),
        (
            "struct Holder {action:fn(fn(bool)->bool,bool)->bool} fn factory()->Holder {Holder {action:apply}}",
            "let helper:fn(fn(bool)->bool,bool)->bool=other_apply;let callback=|| helper(negate,false);let result=callback();assumes result;",
        ),
        (
            "struct Operations {action:fn(fn(bool)->bool,bool)->bool} fn factory()->Operations {Operations {action:apply}}",
            "let ops=Operations {action:apply};let callback=|| ops.action(negate,false);let result=callback();assumes result;",
        ),
        (
            "typealias Carrier=%{helper:fn(fn(bool)->bool,bool)->bool} fn()->bool; fn factory()->Carrier {let helper:fn(fn(bool)->bool,bool)->bool=apply;|| helper(negate,false)}",
            "let helper:fn(fn(bool)->bool,bool)->bool=apply;let inner=|| helper(negate,false);let callback=|| inner();let result=callback();assumes result;",
        ),
    ] {
        let mut package = compile(&format!(
            "trait Retire {{fn drop(*self);}} trait Duplicate {{}} fn negate(value:bool)->bool {{not value}} fn apply(action:fn(bool)->bool,value:bool)->bool {{action(value)}} fn other_apply(action:fn(bool)->bool,value:bool)->bool {{not action(value)}} {declarations} fn entry() {{{body}}}"
        ));
        let factory = package
            .functions
            .iter()
            .find(|f| f.name == "factory")
            .unwrap();
        let nir::Term::Function { result, .. } = factory.signature.callable_signature() else {
            panic!("factory signature")
        };
        let result_type = (**result).clone();
        let callee = Expr {
            source: factory.body.source,
            ty: factory.signature.clone(),
            kind: K::Function(factory.declaration),
        };
        let entry = package
            .functions
            .iter_mut()
            .find(|f| f.name == "entry")
            .unwrap();
        let K::Block { statements, .. } = &mut entry.body.kind else {
            panic!("entry block")
        };
        let closure = statements
            .iter_mut()
            .rev()
            .find_map(|statement| match &mut statement.kind {
                K::Let { value, .. } if matches!(value.kind, K::Closure { .. }) => Some(value),
                _ => None,
            })
            .unwrap();
        let K::Closure { captures, .. } = &mut closure.kind else {
            unreachable!()
        };
        assert_eq!(captures.len(), 1);
        let mut initializer = Expr {
            source: closure.source,
            ty: result_type,
            kind: K::Call {
                callee: Box::new(callee),
                arguments: vec![],
                parameter_bindings: vec![],
            },
        };
        if initializer.ty != captures[0].ty {
            let nir::Term::Nominal { declaration, .. } = initializer.ty.clone() else {
                panic!("projected holder")
            };
            initializer = Expr {
                source: closure.source,
                ty: captures[0].ty.clone(),
                kind: K::Field {
                    value: Box::new(initializer),
                    declaration,
                    index: 0,
                },
            };
        }
        captures[0].value = Some(Box::new(initializer));
        let executable = source_executable(&package, "entry").unwrap();
        let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
            .unwrap()
            .with_cleanup_schedule(&executable.schedule)
            .unwrap();
        assert_eq!(
            vm.invoke_instance(&executable.entry, vec![]).unwrap(),
            Value::Unit
        );
        assert_eq!(
            executed_names(&package, &executable, vm.events()),
            ["entry", "factory", "apply", "negate"]
        );
    }
}

