#[test]
fn enum_parameter_domains_discharge_only_inapplicable_variants() {
    use comptime_interpretor::{Interpreter, Value};
    for (input, expected_value, callback) in [
        ("Choice.none", false, None),
        ("Choice.left(first)", true, Some("first")),
        ("Choice.right(second)", true, Some("second")),
    ] {
        for (declarations, body) in [
            (
                "",
                format!("let result=dispatch({input});assumes result == {expected_value};"),
            ),
            (
                "fn forward(value:T)->T where T {value}",
                format!(
                    "let result=dispatch(forward({input}));assumes result == {expected_value};"
                ),
            ),
            (
                "fn packed(value:Packet)->bool {dispatch(value.value)}",
                format!(
                    "let result=packed(Packet {{value:{input}}});assumes result == {expected_value};"
                ),
            ),
            (
                "",
                format!(
                    "let invoke=|value:Choice| value match {{.none=>false,.left(action)=>action(negate,false),.right(action)=>action(negate,false)}};let result=invoke({input});assumes result == {expected_value};"
                ),
            ),
        ] {
            let package = compile(&format!(
                "trait Retire {{fn drop(*self);}} trait Duplicate {{}} enum Choice {{none,left(fn(fn(bool)->bool,bool)->bool),right(fn(fn(bool)->bool,bool)->bool)}} struct Packet {{value:Choice}} fn negate(value:bool)->bool {{not value}} fn first(action:fn(bool)->bool,value:bool)->bool {{action(value)}} fn second(action:fn(bool)->bool,value:bool)->bool {{action(value)}} fn dispatch(value:Choice)->bool {{value match {{.none=>false,.left(action)=>action(negate,false),.right(action)=>action(negate,false)}}}} {declarations} fn entry() {{{body}}}"
            ));
            let executable = source_executable(&package, "entry")
                .unwrap_or_else(|error| panic!("{body}: {error}"));
            let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_cleanup_schedule(&executable.schedule)
                .unwrap();
            assert_eq!(
                vm.invoke_instance(&executable.entry, vec![]).unwrap(),
                Value::Unit,
                "{body}"
            );
            let names = executed_names(&package, &executable, vm.events());
            assert_eq!(
                names
                    .iter()
                    .filter(|name| name.as_str() == "first" || name.as_str() == "second")
                    .map(String::as_str)
                    .collect::<Vec<_>>(),
                callback.into_iter().collect::<Vec<_>>(),
                "{body}"
            );
            assert_eq!(
                names
                    .iter()
                    .filter(|name| name.as_str() == "negate")
                    .count(),
                usize::from(expected_value)
            );
        }
    }
}

