#[test]
fn cleanup_schedule_rejects_duplicate_transfer_hooks_before_execution() {
    use comptime_interpretor::{ErrorKind, Interpreter};
    let package = compile(
        "trait Retire {fn drop(*self);} trait Duplicate {} struct Ticket {} impl Retire for Ticket {fn drop(*self) {}} fn take(value:Ticket) {} fn entry() {let value=Ticket {};take(value);}",
    );
    let executable = source_executable(&package, "entry").unwrap();
    let mut schedule = executable.schedule.clone();
    let scope = schedule
        .functions
        .iter_mut()
        .find(|scope| !scope.transfers.is_empty())
        .unwrap();
    scope.transfers.push(scope.transfers[0].clone());
    let error = Interpreter::from_iir(&executable.graph, Default::default())
        .unwrap()
        .with_cleanup_schedule(&schedule)
        .err()
        .unwrap();
    assert_eq!(error.kind, ErrorKind::InvalidCallPlan);
}

