#[test]
fn owned_closure_captures_coexist_with_borrowed_pointer_arguments() {
    use comptime_interpretor::{Interpreter, Value};
    for flag in [true, false] {
        for body in [
            "let expected=flag;let callback=|pointer:*bool| {pointer.* = expected;pointer};let result=callback(value.ref);let again=callback(result);again.*",
            "let callback=build(flag);let result=callback(value.ref);result.*",
            "let left=flag;let right=not flag;let callback=if flag {|pointer:*bool| {pointer.* = left;pointer}} else {|pointer:*bool| {pointer.* = not right;pointer}};let result=callback(value.ref);result.*",
            "let held=Held {};let callback=|pointer:*bool| {consume(held);pointer.* = true;pointer};let result=callback(value.ref);result.* and flag",
            "let held=Held {};let callback=|pointer:*bool| {observe(held);pointer.*};let first=callback(value.ref);let second=callback(value.ref);flag",
        ] {
            let package = compile(&format!(
                "trait Retire {{fn drop(*self);}} trait Duplicate {{}} struct Held {{}} impl Retire for Held {{fn drop(*self) {{}}}} fn consume(value:Held) {{}} fn observe(value:Held) {{}} fn build(flag:bool)->%{{flag:bool}} fn(*bool)->*bool {{|pointer:*bool| {{pointer.* = flag;pointer}}}} fn work(flag:bool)->bool {{let value=false;{body}}} fn entry()->bool {{work({flag})}}"
            ));
            // The last body intentionally moves an affine capture twice.
            if body.contains("observe") {
                assert!(
                    source_executable(&package, "entry")
                        .unwrap_err()
                        .contains("unavailable")
                );
                continue;
            }
            let executable = source_executable(&package, "entry")
                .unwrap_or_else(|error| panic!("{body}: {error}"));
            let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_cleanup_schedule(&executable.schedule)
                .unwrap();
            assert_eq!(
                vm.invoke_instance(&executable.entry, vec![]).unwrap(),
                Value::Bool(flag),
                "{body}"
            );
            let names = executed_names(&package, &executable, vm.events());
            assert_eq!(
                names
                    .iter()
                    .filter(|name| name.as_str() == "drop Held")
                    .count(),
                usize::from(body.contains("consume")),
                "{body}: {names:?}"
            );
        }
    }
}

#[test]
fn owned_closure_memory_failure_cleans_capture_and_caller_in_order() {
    use comptime_interpretor::{ErrorKind, Interpreter};
    for consumed in [true, false] {
        let body = if consumed {
            "consume(held);let seen=pointer.*;assumes false;"
        } else {
            "let seen=pointer.*;assumes false;consume(held);"
        };
        let package = compile(&format!(
            "trait Retire {{fn drop(*self);}} trait Duplicate {{}} struct Held {{}} struct Caller {{}} impl Retire for Held {{fn drop(*self) {{}}}} impl Retire for Caller {{fn drop(*self) {{}}}} fn consume(value:Held) {{}} fn entry() {{let caller=Caller {{}};let held=Held {{}};let value=true;let callback=|pointer:*bool| {{{body}}};callback(value.ref);}}"
        ));
        let executable = source_executable(&package, "entry").unwrap();
        let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
            .unwrap()
            .with_cleanup_schedule(&executable.schedule)
            .unwrap();
        assert_eq!(
            vm.invoke_instance(&executable.entry, vec![])
                .unwrap_err()
                .kind,
            ErrorKind::ProgramContractRejected
        );
        assert_eq!(
            executed_names(&package, &executable, vm.events()),
            if consumed {
                vec!["entry", "consume", "drop Held", "drop Caller"]
            } else {
                vec!["entry", "drop Held", "drop Caller"]
            }
        );
    }
}

#[test]
fn captured_named_callable_memory_preserves_candidate_effects_and_results() {
    use comptime_interpretor::{Interpreter, Value};
    for flag in [true, false] {
        for body in [
            "let action=if flag {set} else {clear};let callback=|pointer:*bool| action(pointer);let result=callback(value.ref);result.*",
            "let left=set;let right=clear;let callback=if flag {|pointer:*bool| left(pointer)} else {|pointer:*bool| right(pointer)};let result=callback(value.ref);result.*",
            "let callback=build(flag);let result=callback(value.ref);result.*",
            "let action:fn(*bool)->*bool=forward;let callback=|pointer:*bool|action(set(pointer));let result=callback(value.ref);result.* and flag",
            "var action=set;let callback=|pointer:*bool| {let result=action(pointer);action=clear;result};let first=callback(value.ref);let seen=first.*;let second=callback(value.ref);let after=second.*;assumes not after;seen and flag",
        ] {
            let package = compile(&format!(
                "trait Retire {{fn drop(*self);}} trait Duplicate {{}} fn set(pointer:*bool)->*bool {{pointer.* = true;pointer}} fn clear(pointer:*bool)->*bool {{pointer.* = false;pointer}} fn build(flag:bool)->%{{action:fn(*bool)->*bool}} fn(*bool)->*bool {{let action=if flag {{set}} else {{clear}};|pointer:*bool| action(pointer)}} fn forward(value:T)->T where T {{value}} fn work(flag:bool)->bool {{let value=false;{body}}} fn entry()->bool {{work({flag})}}"
            ));
            let executable = source_executable(&package, "entry")
                .unwrap_or_else(|error| panic!("{body}: {error}"));
            let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_cleanup_schedule(&executable.schedule)
                .unwrap();
            assert_eq!(
                vm.invoke_instance(&executable.entry, vec![]).unwrap(),
                Value::Bool(flag),
                "{body}"
            );
            let names = executed_names(&package, &executable, vm.events());
            if body.starts_with("var") {
                assert_eq!(
                    names.iter().filter(|name| name.as_str() == "set").count(),
                    1
                );
                assert_eq!(
                    names.iter().filter(|name| name.as_str() == "clear").count(),
                    1
                );
            } else if body.contains("forward") {
                assert_eq!(
                    names.iter().filter(|name| name.as_str() == "set").count(),
                    1
                );
                assert_eq!(
                    names
                        .iter()
                        .filter(|name| name.as_str() == "forward")
                        .count(),
                    1
                );
            } else {
                assert!(
                    names
                        .iter()
                        .any(|name| name == if flag { "set" } else { "clear" })
                );
                assert!(
                    !names
                        .iter()
                        .any(|name| name == if flag { "clear" } else { "set" })
                );
            }
        }
    }
}

#[test]
fn captured_memory_callees_cannot_hide_alternative_pointer_results() {
    let package = compile(
        "trait Retire {fn drop(*self);} trait Duplicate {} struct Item {flag:bool} impl Retire for Item {fn drop(*self) {}} fn first(a:*Item,b:*Item)->*Item {a} fn second(a:*Item,b:*Item)->*Item {b} fn entry(flag:bool)->bool {let first_item=Item {flag:true};let second_item=Item {flag:false};let action=if flag {first} else {second};let callback=|a:*Item,b:*Item|action(a,b);let pointer=callback(first_item.ref,second_item.ref);let moved=first_item;pointer.flag.*}",
    );
    assert!(
        source_executable(&package, "entry")
            .unwrap_err()
            .contains("unavailable")
    );
    use comptime_interpretor::{Interpreter, Value};
    let package = compile(
        "trait Retire {fn drop(*self);} trait Duplicate {} fn named(value:*bool)->*bool {value} fn entry(flag:bool)->bool {let value=true;let action=if flag {named} else {|value:*bool| {value.* = false;value}};let callback=|value:*bool|action(value);let pointer=callback(value.ref);pointer.*}",
    );
    let executable = source_executable(&package, "entry").unwrap();
    for flag in [true, false] {
        let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
            .unwrap()
            .with_cleanup_schedule(&executable.schedule)
            .unwrap();
        assert_eq!(
            vm.invoke_instance(&executable.entry, vec![Value::Bool(flag)])
                .unwrap(),
            Value::Bool(flag)
        );
        let names = executed_names(&package, &executable, vm.events());
        assert_eq!(
            names.iter().filter(|name| name.as_str() == "named").count(),
            usize::from(flag),
            "{names:?}"
        );
    }
    let package = compile(
        "trait Retire {fn drop(*self);} trait Duplicate {} struct Item {flag:bool} impl Retire for Item {fn drop(*self) {}} fn first(a:*Item,b:*Item)->*Item {a} fn entry(flag:bool)->bool {let a=Item {flag:true};let b=Item {flag:false};let action=if flag {first} else {|a:*Item,b:*Item|b};let callback=|a:*Item,b:*Item|action(a,b);let pointer=callback(a.ref,b.ref);let moved=b;pointer.flag.*}",
    );
    assert!(
        source_executable(&package, "entry")
            .unwrap_err()
            .contains("unavailable")
    );
}

#[test]
fn captured_callable_fields_supply_memory_footprints_and_track_replacements() {
    use comptime_interpretor::{Interpreter, Value};
    for body in [
        "let ops=Ops {action:set};let callback=|pointer:*bool|ops.action(pointer);let pointer=callback(value.ref);pointer.*",
        "let ops=Ops {action:clear};let callback=|pointer:*bool| {while true {ops.action=set;break;}ops.action(pointer)};let pointer=callback(value.ref);pointer.*",
        "let ops=Nested {pair:(set,false)};let callback=|pointer:*bool| {let (action,_)=ops.pair;action(pointer)};let pointer=callback(value.ref);pointer.*",
        "let ops=Ops {action:set};let callback=|pointer:*bool| {let result=ops.action(pointer);ops.action=clear;result};let first=callback(value.ref);let seen=first.*;let second=callback(value.ref);let after=second.*;assumes not after;seen",
        "var ops=Ops {action:clear};let callback=|pointer:*bool| {ops=Ops {action:set};ops.action(pointer)};let pointer=callback(value.ref);pointer.*",
        "let ops=Ops {action:set};let callback=|pointer:*bool| {let saved=ops;let {action}=saved;action(pointer)};let pointer=callback(value.ref);pointer.*",
        "var action=set;let callback=|pointer:*bool| {let values=(action,do {action=clear;false});let (saved,_)=values;saved(pointer)};let pointer=callback(value.ref);pointer.*",
    ] {
        let package = finite_default_support::compile_with_tuple(&format!(
            "trait Retire {{fn drop(*self);}} trait Duplicate {{}} struct Ops {{action:fn(*bool)->*bool}} struct Nested {{pair:Tuple<fn(*bool)->*bool,bool>}} fn set(pointer:*bool)->*bool {{pointer.* = true;pointer}} fn clear(pointer:*bool)->*bool {{pointer.* = false;pointer}} fn entry()->bool {{let value=false;{body}}}"
        ));
        let executable =
            source_executable(&package, "entry").unwrap_or_else(|error| panic!("{body}: {error}"));
        let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
            .unwrap()
            .with_cleanup_schedule(&executable.schedule)
            .unwrap();
        assert_eq!(
            vm.invoke_instance(&executable.entry, vec![]).unwrap(),
            Value::Bool(true),
            "{body}"
        );
        let names = executed_names(&package, &executable, vm.events());
        assert_eq!(
            names.iter().filter(|name| name.as_str() == "set").count(),
            1,
            "{body}: {names:?}"
        );
        assert_eq!(
            names.iter().filter(|name| name.as_str() == "clear").count(),
            usize::from(body.contains("let second")),
            "{body}: {names:?}"
        );
    }
}

#[test]
fn captured_memory_fields_invalidate_replaced_code_and_join_changed_targets() {
    for update in [
        "if flag {ops.action=second;}",
        "if flag {ops=Ops {action:second};}",
    ] {
        let package = compile(&format!(
            "trait Retire {{fn drop(*self);}} trait Duplicate {{}} struct Item {{flag:bool}} impl Retire for Item {{fn drop(*self) {{}}}} struct Ops {{action:fn(*Item,*Item)->*Item}} fn first(a:*Item,b:*Item)->*Item {{a}} fn second(a:*Item,b:*Item)->*Item {{b}} fn entry(flag:bool)->bool {{let a=Item {{flag:true}};let b=Item {{flag:false}};var ops=Ops {{action:first}};let callback=|a:*Item,b:*Item,flag:bool| {{{update}ops.action(a,b)}};let pointer=callback(a.ref,b.ref,flag);let moved=b;pointer.flag.*}}"
        ));
        let error = source_executable(&package, "entry")
            .err()
            .expect("moved enum must be rejected");
        assert!(error.contains("unavailable"), "{update}: {error}");
    }
    let package = compile(
        "trait Retire {fn drop(*self);} trait Duplicate {} struct Ops {action:fn(*bool)->*bool} fn named(value:*bool)->*bool {value} fn entry()->bool {let value=true;var ops=Ops {action:named};let callback=|value:*bool| {ops=Ops {action:|value:*bool| {value.* = false;value}};ops.action(value)};let result=callback(value.ref);result.*}",
    );
    let executable = source_executable(&package, "entry").unwrap();
    let mut vm = comptime_interpretor::Interpreter::from_iir(&executable.graph, Default::default())
        .unwrap()
        .with_cleanup_schedule(&executable.schedule)
        .unwrap();
    assert_eq!(
        vm.invoke_instance(&executable.entry, vec![]).unwrap(),
        comptime_interpretor::Value::Bool(false)
    );
    assert!(
        !executed_names(&package, &executable, vm.events())
            .iter()
            .any(|name| name == "named"),
        "aggregate replacement must call its anonymous code"
    );
}

