#[test]
fn recursive_callable_cleanup_backedges_keep_each_runtime_frame() {
    use comptime_interpretor::{Interpreter, Value};
    for reject in [false, true] {
        let package = compile(&format!(
            "trait Retire {{fn drop(*self);}} trait Duplicate {{}} struct Frame {{}} impl Retire for Frame {{fn drop(*self) {{}}}} fn first()->bool {{false}} fn second()->bool {{true}} fn descend(action:fn()->bool,remaining:.u32'builtin)->bool {{let frame=Frame {{}};if remaining==0 {{assumes not {reject};return action();}}descend(second,remaining - 1)}} fn entry()->bool {{descend(first,4)}}"
        ));
        let executable = source_executable(&package, "entry").unwrap();
        assert!(!executable.schedule.aliases.is_empty());
        println!("RECURSIVE_CLEANUP_DUMP={}", executable.schedule);
        let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
            .unwrap()
            .with_cleanup_schedule(&executable.schedule)
            .unwrap();
        let result = vm.invoke_instance(&executable.entry, vec![]);
        if reject {
            assert_eq!(
                result.unwrap_err().kind,
                comptime_interpretor::ErrorKind::ProgramContractRejected
            );
        } else {
            assert_eq!(result.unwrap(), Value::Bool(true));
        }
        let names = executed_names(&package, &executable, vm.events());
        assert_eq!(
            names
                .iter()
                .filter(|name| name.as_str() == "descend")
                .count(),
            5,
            "{names:?}"
        );
        assert_eq!(
            names
                .iter()
                .filter(|name| name.as_str() == "drop Frame")
                .count(),
            5,
            "{names:?}"
        );
        assert!(!names.iter().any(|name| name == "first"), "{names:?}");
        assert_eq!(
            names
                .iter()
                .filter(|name| name.as_str() == "second")
                .count(),
            usize::from(!reject),
            "{names:?}"
        );
    }
}

#[test]
fn recursive_cleanup_aliases_reject_malformed_targets_before_execution() {
    use comptime_interpretor::{ErrorKind, Interpreter};
    let package = compile(
        "trait Retire {fn drop(*self);} trait Duplicate {} fn action()->bool {true} fn descend(action:fn()->bool,remaining:.u32'builtin)->bool {if remaining==0 {return action();}descend(action,remaining - 1)} fn entry()->bool {descend(action,3)}",
    );
    let executable = source_executable(&package, "entry").unwrap();
    assert!(!executable.schedule.aliases.is_empty());
    for mutation in 0..5 {
        let mut schedule = executable.schedule.clone();
        match mutation {
            0 => schedule.aliases[0].target = schedule.aliases[0].context.clone(),
            1 => schedule.aliases[0].target.clear(),
            2 => schedule.aliases.push(schedule.aliases[0].clone()),
            3 => {
                let alias = &schedule.aliases[0];
                let target = alias.target.clone();
                let instance = alias.instance.clone();
                schedule
                    .functions
                    .retain(|scope| scope.instance != instance || scope.context != target);
            }
            4 => {
                if let Some(iir::cleanup::ContextKey::Function { callee, .. }) =
                    schedule.aliases[0].context.last_mut()
                {
                    *callee = executable.entry.clone();
                }
            }
            _ => unreachable!(),
        }
        let error = Interpreter::from_iir(&executable.graph, Default::default())
            .unwrap()
            .with_cleanup_schedule(&schedule)
            .err()
            .unwrap();
        assert_eq!(
            error.kind,
            ErrorKind::InvalidCallPlan,
            "mutation {mutation}"
        );
    }
}

#[test]
fn higher_order_named_memory_calls_use_prepared_code_contexts() {
    use comptime_interpretor::{Interpreter, Value};
    for flag in [true, false] {
        for body in [
            "apply(if flag {set} else {clear},pointer)",
            "relay(if flag {set} else {clear},pointer)",
            "factory_apply(pointer,flag)",
            "let invoke=if flag {apply} else {relay};invoke(if flag {set} else {clear},pointer)",
            "aggregate(Ops {action:if flag {set} else {clear}},pointer)",
            "recursive(if flag {set} else {clear},pointer,false)",
            "var action=if flag {set} else {clear};after(action,do {action=clear;pointer})",
        ] {
            let package = compile(&format!(
                "trait Retire {{fn drop(*self);}} trait Duplicate {{}} struct Ops {{action:fn(*bool)->*bool}} fn set(pointer:*bool)->*bool {{pointer.* = true;pointer}} fn clear(pointer:*bool)->*bool {{pointer.* = false;pointer}} fn apply(action:fn(*bool)->*bool,pointer:*bool)->*bool {{action(pointer)}} fn relay(action:fn(*bool)->*bool,pointer:*bool)->*bool {{apply(action,pointer)}} fn factory(flag:bool)->fn(*bool)->*bool {{if flag {{set}} else {{clear}}}} fn factory_apply(pointer:*bool,flag:bool)->*bool {{apply(factory(flag),pointer)}} fn aggregate(ops:Ops,pointer:*bool)->*bool {{ops.action(pointer)}} fn recursive(action:fn(*bool)->*bool,pointer:*bool,stop:bool)->*bool {{if stop {{return action(pointer);}}recursive(action,pointer,true)}} fn after(action:fn(*bool)->*bool,pointer:*bool)->*bool {{apply(action,pointer)}} fn work(flag:bool)->bool {{let value=false;let callback=|pointer:*bool,flag:bool| {{{body}}};let result=callback(value.ref,flag);result.*}} fn entry()->bool {{work({flag})}}"
            ));
            let executable = source_executable(&package, "entry")
                .unwrap_or_else(|error| panic!("{body}: {error}"));
            let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_cleanup_schedule(&executable.schedule)
                .unwrap();
            assert_eq!(
                vm.invoke_instance(&executable.entry, vec![]).unwrap(),
                Value::Bool(flag),
                "{body}"
            );
            let names = executed_names(&package, &executable, vm.events());
            assert_eq!(
                names
                    .iter()
                    .filter(|name| name.as_str() == if flag { "set" } else { "clear" })
                    .count(),
                1,
                "{body}: {names:?}"
            );
            assert!(
                !names
                    .iter()
                    .any(|name| name == if flag { "clear" } else { "set" }),
                "{body}: {names:?}"
            );
        }
    }
}

