#[test]
fn indirect_drop_access_checks_every_pointer_alternative_and_snapshot() {
    use elaboration::verification::{
        PlaceId,
        drop::{PointerMemory, check_access_with_memory},
        ownership::{Place, Shape, State},
    };
    use std::collections::{BTreeMap, BTreeSet};
    let package = compile(
        "trait Retire {fn drop(*self);} struct Link {target:**bool} impl Retire for Link {fn drop(*self) {let observed:bool=self.target;}}",
    );
    world(&package, |world, items| {
        let subject = nominal(&package, "Link", vec![]);
        let Resolution::Selected(selected) =
            luna::protocols::select_drop(&package, world, items, &subject, Budget::default())
                .unwrap()
        else {
            panic!("selected")
        };
        let root = |local| PlaceId { owner: 100, local };
        let place = |local| Place {
            root: root(local),
            fields: vec![],
        };
        let receiver = place(0);
        let mut state = State::default();
        state
            .declare(root(0), &Shape::Fields(vec![Shape::Value]), true, &mut 1000)
            .unwrap();
        for index in 1..4 {
            state
                .declare(root(index), &Shape::Value, true, &mut 1000)
                .unwrap();
        }
        let boolean = nir::Term::Primitive(nir::Primitive::Bool);
        let mut types = BTreeMap::from([
            (root(0), subject),
            (root(1), nir::Term::Pointer(Box::new(boolean.clone()))),
            (root(2), boolean.clone()),
            (root(3), boolean),
        ]);
        let mut slots = BTreeMap::from([
            (
                Place {
                    root: root(0),
                    fields: vec![0],
                },
                BTreeSet::from([place(1)]),
            ),
            (place(1), BTreeSet::from([place(2), place(3)])),
        ]);
        let check = |state: &State,
                     types: &BTreeMap<PlaceId, nir::Term>,
                     slots: &BTreeMap<Place, BTreeSet<Place>>,
                     retired: &[Place],
                     fuel: &mut usize| {
            check_access_with_memory(
                &package,
                world,
                &selected,
                state,
                &receiver,
                Some(PointerMemory {
                    types,
                    slots,
                    enum_domains: &BTreeMap::new(),
                    pointer_conditions: &BTreeMap::new(),
                    retired,
                }),
                fuel,
            )
        };
        let before = state.clone();
        let checked = check(&state, &types, &slots, &[], &mut 10000).unwrap();
        assert!(
            checked
                .targets
                .contains(&BTreeSet::from([place(2), place(3)]))
        );
        assert!(checked.to_string().contains("(targets (access"));
        assert_eq!(state, before);
        assert!(
            check(&state, &types, &slots, &[place(3)], &mut 10000)
                .unwrap_err()
                .contains("earlier cleanup")
        );
        assert!(
            check(&state, &types, &slots, &[], &mut 0)
                .unwrap_err()
                .contains("budget")
        );
        state.take(&place(3)).unwrap();
        assert!(
            check(&state, &types, &slots, &[], &mut 10000)
                .unwrap_err()
                .contains("unavailable")
        );
        state.install(&place(3)).unwrap();
        types.insert(root(3), nir::Term::Primitive(nir::Primitive::U8));
        assert!(
            check(&state, &types, &slots, &[], &mut 10000)
                .unwrap_err()
                .contains("type disagrees")
        );
        types.insert(root(3), nir::Term::Primitive(nir::Primitive::Bool));
        slots.remove(&place(1));
        assert!(
            check(&state, &types, &slots, &[], &mut 10000)
                .unwrap_err()
                .contains("provenance")
        );
        slots.insert(place(1), BTreeSet::new());
        assert!(
            check(&state, &types, &slots, &[], &mut 10000)
                .unwrap_err()
                .contains("provenance")
        );
    });
}

