    let package = compile(&format!(
        "{prefix} fn entry()->bool {{let first=false;let second=false;var pointer=first.ref;while true {{Bundle {{watch:Watch {{target:pointer}},marker:Marker {{}},value:do {{pointer=second.ref;break;true}}}};}}first and not second}}"
    ));
