#[test]
fn effect_escape_checkpoint_excludes_transferred_inputs_and_preserves_resume_state() {
    use elaboration::verification::moves::{CleanupAction, CleanupReason};
    let package = compile(
        "trait Duplicate {} trait Retire {fn drop(*self);}
        struct Ticket {} impl Retire for Ticket {fn drop(*self) {}}
        effect send(item:Ticket)->bool;
        fn subject(sent:Ticket, kept:Ticket)->#send bool {send(sent)#}",
    );
    let function = package
        .functions
        .iter()
        .find(|f| f.name == "subject")
        .unwrap();
    let report = cleanup_report(&package, "subject").unwrap();
    let exits: Vec<_> = report
        .cleanup_sites
        .iter()
        .filter(|s| s.reason == CleanupReason::EffectEscape)
        .collect();
    assert_eq!(exits.len(), 1, "{report}");
    assert_eq!(exits[0].actions.len(), 1, "{report}");
    let CleanupAction::Planned { candidate, .. } = &exits[0].actions[0] else {
        panic!("{report}")
    };
    let CleanupAction::Owned { remaining, .. } = candidate.as_ref() else {
        panic!("{report}")
    };
    assert_eq!(
        remaining.place.root.local, function.parameters[1].index,
        "{report}"
    );
    assert_eq!(
        remaining.place.root.owner,
        u64::from(function.parameters[1].owner),
        "{report}"
    );
    assert_eq!(
        report.exits.len(),
        1,
        "escape must not become a normal return: {report}"
    );
    assert!(
        report
            .cleanup_sites
            .iter()
            .any(|s| s.reason == CleanupReason::FunctionEnd && s.actions.len() == 1),
        "{report}"
    );
    assert!(report.to_string().contains("(reason effect-escape)"));
    assert_eq!(
        iir::cleanup::Boundary::EffectEscape.to_string(),
        "effect-escape"
    );
}

#[test]
fn effect_escape_checkpoint_keeps_enclosing_partial_construction_in_order() {
    use elaboration::verification::moves::{CleanupAction, CleanupReason};
    let package = compile(
        "trait Duplicate {} trait Retire {fn drop(*self);}
        struct Ticket {} impl Retire for Ticket {fn drop(*self) {}}
        effect poll()->bool;
        fn subject()->#poll bool {let older=Ticket {};let pair=(Ticket {},poll()#);true}",
    );
    let report = cleanup_report(&package, "subject").unwrap();
    let checkpoint = report
        .cleanup_sites
        .iter()
        .find(|s| s.reason == CleanupReason::EffectEscape)
        .unwrap();
    assert_eq!(checkpoint.actions.len(), 2, "{report}");
    assert!(
        matches!(&checkpoint.actions[0], CleanupAction::Planned {candidate,..} if matches!(candidate.as_ref(),CleanupAction::Prepared {value,..} if value.slot==0)),
        "{report}"
    );
    assert!(
        matches!(&checkpoint.actions[1], CleanupAction::Planned {candidate,..} if matches!(candidate.as_ref(),CleanupAction::Owned {..})),
        "{report}"
    );
}

