#[test]
fn scheduled_handler_returned_callable_cannot_hide_handler_local_pointer() {
    for (types, body) in [
        (
            "typealias Callback=%{pointer:*bool} fn()->*bool;",
            "let local=true;let pointer=local.ref;return || pointer;",
        ),
        (
            "typealias Callback=%{pointer:*bool} fn()->*bool;",
            "let local=true;let pointer=local.ref;let callback=|| pointer;return callback;",
        ),
        (
            "struct Holder {pointer:*bool} typealias Callback=%{holder:Holder} fn()->Holder;",
            "let local=true;let holder=Holder {pointer:local.ref};return || holder;",
        ),
        (
            "typealias Inner=%{pointer:*bool} fn()->*bool;typealias Callback=%{inner:Inner} fn()->Inner;",
            "let local=true;let pointer=local.ref;let inner=|| pointer;return || inner;",
        ),
    ] {
        let package = compile(&format!(
            "trait Duplicate {{}} trait Retire {{fn drop(*self);}} {types}
            effect poll()->Callback;fn subject()->#poll Callback {{poll()#}}
            fn build()->Callback {{subject()# {{poll()=>do {{{body}}},}}}}"
        ));
        // Reject at the producing function, even without invoking the callback.
        let error = source_executable(&package, "build").unwrap_err();
        assert!(error.contains("escaping provenance"), "{body}: {error}");
    }
}

