#[test]
fn optional_inline_call_chains_preserve_defaults_contracts_and_owned_returns() {
    // Inline expansion adds nested blocks and conditionals. Exercise all
    // contract failures and cleanup paths on a fixed ordinary thread stack,
    // independently of RUST_MIN_STACK in the surrounding test runner.
    std::thread::Builder::new()
        .name("inline-contract-cleanup".into())
        .stack_size(2 * 1024 * 1024)
        .spawn(check_optional_inline_call_chains)
        .unwrap()
        .join()
        .unwrap();
}

fn check_optional_inline_call_chains() {
    use comptime_interpretor::{ErrorKind, Interpreter, Value};
    let original=compile("trait Duplicate {} trait Retire {fn drop(*self);}
        struct Caller {} struct Input {} struct Outer {} struct Middle {} struct Leaf {} struct Output {}
        impl Retire for Caller {fn drop(*self) {}} impl Retire for Input {fn drop(*self) {}}
        impl Retire for Outer {fn drop(*self) {}} impl Retire for Middle {fn drop(*self) {}}
        impl Retire for Leaf {fn drop(*self) {}} impl Retire for Output {fn drop(*self) {}}
        fn make_input()->Input {Input {}} fn mark(value:bool)->bool {value}
        inline fn leaf(input:Input,early:bool,.chosen:bool=mark(early))->Output
            where requires early == early, ensures true {
            let local=Leaf {};if chosen {return Output {};}Output {}
        }
        inline fn middle(input:Input,early:bool)->Output where requires early == early, ensures true {
            let local=Middle {};return leaf(input,early);
        }
        inline fn outer(input:Input,early:bool)->Output where requires early == early, ensures true {
            let local=Outer {};middle(input,early)
        }
        fn entry(early:bool)->bool {let caller=Caller {};let output=outer(make_input(),early);true}");
    for early in [false, true] {
        for (target, failure) in [
            ("leaf", "none"),
            ("outer", "entry"),
            ("outer", "result"),
            ("middle", "entry"),
            ("middle", "result"),
            ("leaf", "entry"),
            ("leaf", "result"),
        ] {
            let mut baseline = None;
            for budget in [None, Some(500), Some(2000), Some(1000000)] {
                let expanded = budget.is_some();
                let mut package = original.clone();
                let function = package
                    .functions
                    .iter_mut()
                    .find(|f| f.name == target)
                    .unwrap();
                let predicate = match failure {
                    "entry" => function.preconditions.first_mut(),
                    "result" => function.postconditions.first_mut(),
                    _ => None,
                };
                if let Some(predicate) = predicate {
                    predicate.kind =
                        nir::program::ExprKind::Literal(nir::program::Literal::Bool(false));
                }
                if let Some(budget) = budget {
                    let report =
                        elaboration::program::inlining::expand(&mut package, &mut { budget });
                    if budget == 1000000 {
                        assert!(report.unwrap().expanded >= 3);
                    }
                }
                let executable = source_executable(&package, "entry").unwrap();
                let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                    .unwrap()
                    .with_cleanup_schedule(&executable.schedule)
                    .unwrap();
                let result = vm
                    .invoke_instance(&executable.entry, vec![Value::Bool(early)])
                    .map_err(|error| error.kind);
                assert_eq!(
                    result,
                    if failure == "none" {
                        Ok(Value::Bool(true))
                    } else {
                        Err(ErrorKind::ProgramContractRejected)
                    },
                    "{target}/{failure}/{early}/{expanded}"
                );
                let names = executed_names(&package, &executable, vm.events())
                    .into_iter()
                    .filter(|name| !matches!(name.as_str(), "outer" | "middle" | "leaf"))
                    .collect::<Vec<_>>();
                assert_eq!(
                    names
                        .iter()
                        .filter(|name| name.as_str() == "make_input")
                        .count(),
                    1
                );
                let reaches_leaf = !(failure == "entry" && target != "leaf");
                assert_eq!(
                    names.iter().filter(|name| name.as_str() == "mark").count(),
                    usize::from(reaches_leaf)
                );
                assert_eq!(
                    names
                        .iter()
                        .filter(|name| name.as_str() == "drop Input")
                        .count(),
                    1
                );
                assert_eq!(
                    names
                        .iter()
                        .filter(|name| name.as_str() == "drop Output")
                        .count(),
                    usize::from(failure != "entry")
                );
                if let Some(baseline) = &baseline {
                    assert_eq!(&names, baseline, "{target}/{failure}/{early}");
                } else {
                    baseline = Some(names);
                }
            }
        }
    }
}

#[test]
fn optional_inline_guard_calls_keep_observation_execution_usable() {
    use comptime_interpretor::{Interpreter, Value};
    for modifier in ["inline", "quote"] {
        for body in [
            "value",
            "return value;",
            "if value {return true;} else {return false;}",
            "if value {return true;}false",
            "while value {return true;}false",
            "if false {assumes false;return true;}value",
            "if true {return value;}assumes false;false",
            "let answer=true match {false=>do {assumes false;false},_=>value};if value {return answer;}answer",
            "let answer=true match {_ if false=>do {assumes false;false},_=>value};if value {return answer;}answer",
            "let answer=true match {_ and observed(value) is chosen=>chosen};if value {return answer;}answer",
            "let _ and observed(value) is chosen=false;if value {return chosen;}chosen",
            "let true=value else {return false;};true",
            "let chosen if chosen=value else {return false;};true",
            "while true {let true=value else {return false;};return true;}false",
            "var _ and observed(value) is chosen=false;chosen=not chosen;if chosen {return false;}true",
            "var ((true as chosen) or (false as chosen))=value;chosen=not chosen;if chosen {return false;}true",
            "var local=value;while local {local=false;return true;}false",
            "if value {return observed(true);}observed(false)",
            "value match {true=>do {return true;},false=>do {return false;}}",
            "if value {true} else {false}",
            "value match {true=>true,false=>false}",
            "let selected=value; selected",
        ] {
            let original = compile(&format!(
                "trait Duplicate {{}} trait Retire {{fn drop(*self);}}
        fn default_value(value:bool)->bool {{value}}
        fn observed(value:bool)->bool {{value}}
        {modifier} fn accept(value:bool,.selected:bool=default_value(value))->bool {{{body}}}
        fn entry(input:bool)->bool {{input match {{value if accept(value)=>true,_=>false}}}}"
            ));
            for expanded in [false, true] {
                let mut package = original.clone();
                if expanded {
                    let report =
                        elaboration::program::inlining::expand(&mut package, &mut 1000000).unwrap();
                    if modifier == "inline" {
                        assert!(report.expanded > 0);
                    }
                }
                let executable = source_executable(&package, "entry").unwrap();
                for input in [false, true] {
                    let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                        .unwrap()
                        .with_cleanup_schedule(&executable.schedule)
                        .unwrap();
                    assert_eq!(
                        vm.invoke_instance(&executable.entry, vec![Value::Bool(input)])
                            .unwrap(),
                        Value::Bool(input)
                    );
                    let names = executed_names(&package, &executable, vm.events());
                    assert_eq!(
                        names
                            .iter()
                            .filter(|name| name.as_str() == "default_value")
                            .count(),
                        1
                    );
                    assert_eq!(
                        names
                            .iter()
                            .filter(|name| name.as_str() == "observed")
                            .count(),
                        usize::from(body.contains("observed"))
                    );
                }
            }
        }
    }
}

#[test]
fn owned_observation_locals_preserve_cleanup_across_expansion() {
    use comptime_interpretor::{Interpreter, Value};
    for modifier in ["", "inline", "quote"] {
        for (body, drops) in [
            ("let held=Held {};value", 1),
            ("let held=Box {first:Held {},second:Held {}};value", 2),
            ("var held=Held {};held=Held {};value", 2),
            ("let held=Held {};if value {return true;}false", 1),
            (
                "let held=Box {first:Held {},second:Held {}};if value {return true;}false",
                2,
            ),
            (
                "var held=Held {};held=Held {};if value {return true;}false",
                2,
            ),
            (
                "let held=Choice.some(Held {});if value {return true;}false",
                1,
            ),
            (
                "let held=Choice.some(Held {});let .some(item)=held else {return false;};if value {return true;}false",
                1,
            ),
            (
                "while true {let held=Held {};if value {return true;}break;}false",
                1,
            ),
        ] {
            let original=compile(&format!("trait Duplicate {{}} trait Retire {{fn drop(*self);}}
                struct Held {{}} struct Box {{first:Held,second:Held}} enum Choice {{none,some(Held)}}
                fn retired() {{}}
                impl Retire for Held {{fn drop(*self) {{retired();}}}}
                {modifier} fn accept(value:bool)->bool {{{body}}}
                fn entry(value:bool)->bool {{value match {{_ if accept(value)=>true,_=>false}}}}"));
            for expanded in [false, true] {
                let mut package = original.clone();
                if expanded {
                    elaboration::program::inlining::expand(&mut package, &mut 1000000).unwrap();
                }
                let executable = source_executable(&package, "entry")
                    .unwrap_or_else(|e| panic!("{modifier} expanded={expanded} {body}: {e}"));
                for value in [false, true] {
                    let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                        .unwrap()
                        .with_cleanup_schedule(&executable.schedule)
                        .unwrap();
                    assert_eq!(
                        vm.invoke_instance(&executable.entry, vec![Value::Bool(value)])
                            .unwrap(),
                        Value::Bool(value)
                    );
                    let names = executed_names(&package, &executable, vm.events());
                    assert_eq!(
                        names
                            .iter()
                            .filter(|name| name.as_str() == "retired")
                            .count(),
                        drops,
                        "{modifier} expanded={expanded} {body}: {names:?}"
                    );
                }
            }
        }
    }
}

#[test]
fn owned_observation_arguments_transfer_private_resources_once() {
    use comptime_interpretor::{Interpreter, Value};
    for body in [
        "inspect(Held {flag:value})",
        "inspect(make(value))",
        "inspect_bool(make(value).flag)",
        "let held=make(value);inspect(do {held})",
        "let held=Held {flag:value};inspect(held)",
        "let held=make(value);inspect(held)",
        "let boxed=Box {held:make(value)};inspect(boxed.held)",
        "let held=make(value);with_seen(held)",
        "with_default(value)",
        "with_factory(value)",
        "with_default(not value,.held=Held {flag:value})",
        "inspect_ops(Ops {held:make(not value),action:invert})",
        "let ops=Ops {held:make(not value),action:invert};inspect_ops(ops)",
    ] {
        let package = compile(&format!(
            "trait Duplicate {{}} trait Retire {{fn drop(*self);}}
            struct Held {{flag:bool}} struct Box {{held:Held}}
            fn retired() {{}} impl Retire for Held {{fn drop(*self) {{retired();}}}}
            inline fn make(flag:bool)->Held {{Held {{flag:flag}}}}
            inline fn inspect(held:Held)->bool {{held.flag}}
            inline fn inspect_bool(flag:bool)->bool {{flag}}
            typealias Action=fn(bool)->bool;impl Duplicate for Action {{}}
            struct Ops {{held:Held,action:Action}}
            fn invert(flag:bool)->bool {{not flag}}
            inline fn inspect_ops(ops:Ops)->bool {{ops.action(ops.held.flag)}}
            inline fn with_seen(held:Held,.flag:bool=held.flag)->bool {{flag}}
            fn identity(value:bool)->bool {{value}}
            inline fn with_default(value:bool,.held:Held=(Held {{flag:identity(value)}}))->bool {{held.flag}}
            inline fn with_factory(value:bool,.held:Held=make(value))->bool {{held.flag}}
            fn entry(value:bool)->bool {{false match {{_ if do {{{body}}}=>true,_=>false}}}}"
        ));
        for expanded in [false, true] {
            let mut package = package.clone();
            if expanded {
                let report =
                    elaboration::program::inlining::expand(&mut package, &mut 1000000).unwrap();
                assert!(report.expanded > 0, "{body}: {report}");
            }
            let executable =
                source_executable(&package, "entry").unwrap_or_else(|e| panic!("{body}: {e}"));
            for value in [false, true] {
                let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                    .unwrap()
                    .with_cleanup_schedule(&executable.schedule)
                    .unwrap();
                assert_eq!(
                    vm.invoke_instance(&executable.entry, vec![Value::Bool(value)])
                        .unwrap(),
                    Value::Bool(value)
                );
                let names = executed_names(&package, &executable, vm.events());
                assert_eq!(
                    names
                        .iter()
                        .filter(|name| name.as_str() == "retired")
                        .count(),
                    1,
                    "{body}: {names:?}"
                );
            }
        }
    }
}

#[test]
fn finite_factory_postcondition_failure_retires_result_before_caller() {
    use comptime_interpretor::{ErrorKind, Event, Interpreter, Value};
    use nir::program::{ExprKind as K, Literal};
    let selectors = luna::protocols::type_constructors::Selectors {
        copy: Some("input.Duplicate"),
        drop: Some("input.Retire"),
        ..Default::default()
    };
    for (params, result, contract, args, checks) in [
        ("", "result:Config", "ensures result.flag", "", 1),
        (
            "flag:bool",
            "Config",
            "requires flag, ensures flag",
            "true",
            2,
        ),
    ] {
        for body in ["Config {flag:true}", "return Config {flag:true};"] {
            let source = format!(
                "trait Duplicate {{}} trait Retire {{fn drop(*self);}}
                struct Config {{flag:bool}} struct Caller {{}}
                fn retired() {{}} fn caller_retired() {{}} fn taken() {{}}
                impl Retire for Config {{fn drop(*self) {{retired();}}}}
                impl Retire for Caller {{fn drop(*self) {{caller_retired();}}}}
                inline fn factory({params})->{result} where {contract} {{{body}}}
                inline fn take(.config:Config=factory({args}))->bool {{taken();config.flag}}
                fn entry()->bool {{let caller=Caller {{}};take()}}"
            );
            let package = finite_default_support::compile_with_source_bindings(
                &source,
                &Default::default(),
                selectors,
            )
            .unwrap_or_else(|e| panic!("{result}: {body}: {e}"));
            for reject in [false, true] {
                for expanded in [false, true] {
                    let mut package = package.clone();
                    if reject {
                        // Inject runtime rejection only after source proof checking.
                        package
                            .functions
                            .iter_mut()
                            .find(|f| f.name == "factory")
                            .unwrap()
                            .postconditions[0]
                            .kind = K::Literal(Literal::Bool(false));
                    }
                    if expanded {
                        assert!(
                            elaboration::program::inlining::expand(&mut package, &mut 1000000)
                                .unwrap()
                                .expanded
                                > 0
                        );
                    }
                    let executable = source_executable(&package, "entry").unwrap();
                    let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                        .unwrap()
                        .with_cleanup_schedule(&executable.schedule)
                        .unwrap();
                    let value = vm.invoke_instance(&executable.entry, vec![]);
                    if reject {
                        assert_eq!(value.unwrap_err().kind, ErrorKind::ProgramContractRejected);
                    } else {
                        assert_eq!(value.unwrap(), Value::Bool(true));
                    }
                    assert_eq!(
                        vm.events()
                            .iter()
                            .filter(|event| matches!(event, Event::CheckPredicate { .. }))
                            .count(),
                        checks,
                        "{result}, {body}, expanded={expanded}"
                    );
                    let trace = executed_names(&package, &executable, vm.events())
                        .into_iter()
                        .filter(|n| matches!(n.as_str(), "taken" | "retired" | "caller_retired"))
                        .collect::<Vec<_>>();
                    let expected = if reject {
                        vec!["retired", "caller_retired"]
                    } else {
                        vec!["taken", "retired", "caller_retired"]
                    };
                    assert_eq!(trace, expected, "{result}, {body}, expanded={expanded}");
                }
            }
        }
    }
}

#[test]
fn finite_default_factory_cleanup_runs_once_in_each_scope() {
    use comptime_interpretor::{Interpreter, Value};
    let selectors = luna::protocols::type_constructors::Selectors {
        copy: Some("input.Duplicate"),
        drop: Some("input.Retire"),
        ..Default::default()
    };
    for (body, expected) in [
        (
            "let scratch=Scratch {};let result=Config {flag:true};result",
            vec!["scratch_retired", "config_retired"],
        ),
        (
            "var result=Config {flag:false};result=Config {flag:true};result",
            vec!["config_retired", "config_retired"],
        ),
        ("pass(Config {flag:true})", vec!["config_retired"]),
        (
            "let config=Config {flag:true};let flag=inspect(config);Config {flag:flag}",
            vec!["config_retired", "config_retired"],
        ),
        (
            "let flag=apply(Config {flag:true},inspect);Config {flag:flag}",
            vec!["config_retired", "config_retired"],
        ),
        (
            "let config=Config {flag:true};let compute=|| config.flag;let flag=compute();Config {flag:flag}",
            vec!["config_retired", "config_retired"],
        ),
        (
            "let config=Config {flag:true};let compute=|| inspect(config);let flag=compute();Config {flag:flag}",
            vec!["config_retired", "config_retired"],
        ),
        (
            "let config=Config {flag:true};let unused=|| {spin();config.flag};Config {flag:true}",
            vec!["config_retired", "config_retired"],
        ),
    ] {
        let source = format!(
            "trait Duplicate {{}} trait Retire {{fn drop(*self);}}
            struct Scratch {{}} struct Config {{flag:bool}}
            fn scratch_retired() {{}} fn config_retired() {{}} fn spin() {{spin();}}
            impl Retire for Scratch {{fn drop(*self) {{scratch_retired();}}}}
            impl Retire for Config {{fn drop(*self) {{config_retired();}}}}
            typealias Inspect=fn(Config)->bool;impl Duplicate for Inspect {{}}
            inline fn inspect(config:Config)->bool {{config.flag}}
            inline fn pass(config:Config)->Config {{config}}
            fn apply(config:Config,callback:Inspect)->bool {{callback(config)}}
            inline fn factory()->Config {{{body}}}
            inline fn take(.config:Config=factory())->bool {{config.flag}}
            fn entry()->bool {{take()}}"
        );
        let package = finite_default_support::compile_with_source_bindings(
            &source,
            &Default::default(),
            selectors,
        )
        .unwrap();
        for expanded in [false, true] {
            let mut package = package.clone();
            if expanded {
                assert!(
                    elaboration::program::inlining::expand(&mut package, &mut 1000000)
                        .unwrap()
                        .expanded
                        > 0
                );
            }
            let executable = source_executable(&package, "entry").unwrap();
            let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_cleanup_schedule(&executable.schedule)
                .unwrap();
            assert_eq!(
                vm.invoke_instance(&executable.entry, vec![]).unwrap(),
                Value::Bool(true)
            );
            let trace = executed_names(&package, &executable, vm.events())
                .into_iter()
                .filter(|name| matches!(name.as_str(), "scratch_retired" | "config_retired"))
                .collect::<Vec<_>>();
            assert_eq!(trace, expected, "expanded={expanded}: {body}");
        }
    }
}

#[test]
fn stable_constructor_defaults_evaluate_fields_once() {
    use comptime_interpretor::{Interpreter, Value};
    for (ty, expression, body) in [
        ("Config", "(Config {flag:compute(value)})", "config.flag"),
        ("Config", "make_config(value)", "config.flag"),
        ("Config", "forward(value)", "config.flag"),
        (
            "Choice",
            "make_choice(value)",
            "config match {.some(flag)=>flag,.none=>false}",
        ),
        (
            "Choice",
            "Choice.some(compute(value))",
            "config match {.some(flag)=>flag,.none=>false}",
        ),
    ] {
        let package = compile(&format!(
            "trait Duplicate {{}} trait Retire {{fn drop(*self);}}
            struct Config {{flag:bool}} enum Choice {{none,some(bool)}}
            fn retired() {{}}
            impl Retire for Config {{fn drop(*self) {{retired();}}}}
            impl Retire for Choice {{fn drop(*self) {{retired();}}}}
            fn compute(value:bool)->bool {{not value}}
            fn make_config(value:bool)->Config {{Config {{flag:compute(value)}}}}
            fn forward(value:bool)->Config {{if value {{return make_config(value);}}make_config(value)}}
            fn make_choice(value:bool)->Choice {{return Choice.some(compute(value));}}
            fn inspect(value:bool,.config:{ty}={expression})->bool {{{body}}}
            fn entry(value:bool)->bool {{inspect(value)}}"
        ));
        let executable = source_executable(&package, "entry").unwrap();
        for value in [false, true] {
            let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_cleanup_schedule(&executable.schedule)
                .unwrap();
            assert_eq!(
                vm.invoke_instance(&executable.entry, vec![Value::Bool(value)])
                    .unwrap(),
                Value::Bool(!value)
            );
            let trace = executed_names(&package, &executable, vm.events());
            for name in ["compute", "retired"] {
                assert_eq!(
                    trace.iter().filter(|n| n.as_str() == name).count(),
                    1,
                    "{ty}: {trace:?}"
                );
            }
        }
    }
}

#[test]
fn observation_cleanup_checks_nested_local_destructors() {
    use comptime_interpretor::{Interpreter, Value};
    for nested in ["", "assumes false;", "let again=Outer {};"] {
        let package=compile(&format!("trait Duplicate {{}} trait Retire {{fn drop(*self);}}
            struct Outer {{}} struct Inner {{}}
            impl Retire for Inner {{fn drop(*self) {{{nested}}}}}
            impl Retire for Outer {{fn drop(*self) {{let inner=Inner {{}};}}}}
            fn entry(value:bool)->bool {{false match {{_ if do {{let outer=Outer {{}};value}}=>true,_=>false}}}}"));
        if !nested.is_empty() {
            let error = source_executable(&package, "entry").unwrap_err();
            assert!(
                error.contains("failure-path") || error.contains("budget"),
                "{nested}: {error}"
            );
            continue;
        }
        let executable = source_executable(&package, "entry").unwrap();
        for value in [false, true] {
            let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_cleanup_schedule(&executable.schedule)
                .unwrap();
            assert_eq!(
                vm.invoke_instance(&executable.entry, vec![Value::Bool(value)])
                    .unwrap(),
                Value::Bool(value)
            );
            let trace = executed_names(&package, &executable, vm.events())
                .into_iter()
                .filter(|name| name.starts_with("drop "))
                .collect::<Vec<_>>();
            assert_eq!(trace, ["drop Outer", "drop Inner"]);
        }
    }
}

#[test]
fn observation_nested_cleanup_preserves_generic_selection() {
    use comptime_interpretor::{Interpreter, Value};
    for kind in ["Safe", "Bad"] {
        let package=compile(&format!("trait Duplicate {{}} trait Retire {{fn drop(*self);}}
            struct Safe {{}} struct Bad {{}} struct Inner where T {{}} struct Outer {{}}
            impl Retire for Inner<Safe> {{fn drop(*self) {{}}}}
            impl Retire for Inner<Bad> {{fn drop(*self) {{assumes false;}}}}
            fn nested() where T {{let inner=Inner<T> {{}};}}
            impl Retire for Outer {{fn drop(*self) {{nested<{kind}>();}}}}
            fn entry()->bool {{false match {{_ if do {{let outer=Outer {{}};true}}=>true,_=>false}}}}"));
        if kind == "Bad" {
            let error = source_executable(&package, "entry").unwrap_err();
            assert!(error.contains("failure-path"), "{error}");
        } else {
            let executable = source_executable(&package, "entry").unwrap();
            let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_cleanup_schedule(&executable.schedule)
                .unwrap();
            assert_eq!(
                vm.invoke_instance(&executable.entry, vec![]).unwrap(),
                Value::Bool(true)
            );
            let trace = executed_names(&package, &executable, vm.events());
            assert_eq!(
                trace
                    .iter()
                    .filter(|name| name.starts_with("drop "))
                    .count(),
                2,
                "{trace:?}"
            );
        }
    }
}

#[test]
fn expanded_postcondition_rejection_preserves_result_and_frame_cleanup() {
    use comptime_interpretor::{ErrorKind, Event, Interpreter, Value};
    use nir::program::{ExprKind as K, Literal};
    for body in ["return Result {};", "Result {}"] {
        for reject in [false, true] {
            let mut traces = vec![];
            for mode in ["ordinary", "inline", "quote"] {
                let qualifier = if mode == "quote" { "quote" } else { "inline" };
                let mut package=compile(&format!("trait Duplicate {{}} trait Retire {{fn drop(*self);}}
                    struct Arg {{}} struct Temp {{flag:bool}} struct Caller {{}} struct Body {{}} struct Result {{}}
                    impl Retire for Arg {{fn drop(*self) {{}}}} impl Retire for Temp {{fn drop(*self) {{}}}}
                    impl Retire for Caller {{fn drop(*self) {{}}}} impl Retire for Body {{fn drop(*self) {{}}}}
                    impl Retire for Result {{fn drop(*self) {{}}}}
                    fn make()->Temp {{Temp {{flag:true}}}}
                    {qualifier} fn inspect(arg:Arg,flag:bool)->result:Result where ensures true {{let local=Body {{}};{body}}}
                    fn entry() {{let caller=Caller {{}};let result=inspect(Arg {{}},make().flag);}}"));
                // Exercise runtime postcondition failure after source proof checking.
                if reject {
                    for function in &mut package.functions {
                        for predicate in &mut function.postconditions {
                            predicate.kind = K::Literal(Literal::Bool(false));
                        }
                        nir::visit::expression_mut(&mut function.body, &mut 100000, |expr, _| {
                            if let K::EnsurePredicate(predicate) = &mut expr.kind {
                                predicate.kind = K::Literal(Literal::Bool(false));
                            }
                            Ok(())
                        })
                        .unwrap();
                    }
                }
                if mode == "inline" {
                    assert!(
                        elaboration::program::inlining::expand(&mut package, &mut 1000000)
                            .unwrap()
                            .expanded
                            > 0
                    );
                }
                let executable = source_executable(&package, "entry")
                    .unwrap_or_else(|e| panic!("{mode}, {body}, reject={reject}: {e}"));
                let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                    .unwrap()
                    .with_cleanup_schedule(&executable.schedule)
                    .unwrap();
                let result = vm.invoke_instance(&executable.entry, vec![]);
                if reject {
                    assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
                } else {
                    assert_eq!(result.unwrap(), Value::Unit);
                }
                assert_eq!(
                    vm.events()
                        .iter()
                        .filter(|event| matches!(event, Event::CheckPredicate { .. }))
                        .count(),
                    1,
                    "{mode}: {body}"
                );
                let trace = executed_names(&package, &executable, vm.events())
                    .into_iter()
                    .filter(|name| name.starts_with("drop "))
                    .collect::<Vec<_>>();
                for name in [
                    "drop Arg",
                    "drop Temp",
                    "drop Caller",
                    "drop Body",
                    "drop Result",
                ] {
                    assert_eq!(
                        trace.iter().filter(|n| n.as_str() == name).count(),
                        1,
                        "{mode}: {trace:?}"
                    );
                }
                traces.push(trace);
            }
            assert_eq!(traces[0], traces[1], "inline: {body}, reject={reject}");
            assert_eq!(traces[0], traces[2], "quote: {body}, reject={reject}");
        }
    }
}

#[test]
fn expanded_argument_cleanup_matches_failure_and_early_return_paths() {
    use comptime_interpretor::{ErrorKind, Interpreter, Value};
    for (last, body, rejected) in [
        ("fail()", "true", true),
        ("true", "let local=Body {};assumes false;true", true),
        (
            "true",
            "let local=Body {};if flag {return true;}false",
            false,
        ),
    ] {
        let mut traces = vec![];
        for mode in ["ordinary", "inline", "quote"] {
            let qualifier = if mode == "quote" { "quote" } else { "inline" };
            let mut package = compile(&format!(
                "trait Duplicate {{}} trait Retire {{fn drop(*self);}}
                struct Arg {{}} struct Temp {{flag:bool}} struct Caller {{}} struct Body {{}}
                impl Retire for Arg {{fn drop(*self) {{}}}}
                impl Retire for Temp {{fn drop(*self) {{}}}}
                impl Retire for Caller {{fn drop(*self) {{}}}}
                impl Retire for Body {{fn drop(*self) {{}}}}
                fn fail()->bool {{assumes false;true}}
                {qualifier} fn make()->Temp {{Temp {{flag:true}}}}
                {qualifier} fn inspect(arg:Arg,flag:bool,last:bool)->bool {{{body}}}
                fn entry()->bool {{let caller=Caller {{}};inspect(Arg {{}},make().flag,{last})}}"
            ));
            if mode == "inline" {
                assert!(
                    elaboration::program::inlining::expand(&mut package, &mut 1000000)
                        .unwrap()
                        .expanded
                        > 0
                );
            }
            let executable = source_executable(&package, "entry")
                .unwrap_or_else(|e| panic!("{mode}, {last}, {body}: {e}"));
            let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_cleanup_schedule(&executable.schedule)
                .unwrap();
            let result = vm.invoke_instance(&executable.entry, vec![]);
            if rejected {
                assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
            } else {
                assert_eq!(result.unwrap(), Value::Bool(true));
            }
            let trace = executed_names(&package, &executable, vm.events())
                .into_iter()
                .filter(|name| name.starts_with("drop "))
                .collect::<Vec<_>>();
            for name in ["drop Arg", "drop Temp", "drop Caller"] {
                assert_eq!(
                    trace.iter().filter(|n| n.as_str() == name).count(),
                    1,
                    "{mode}: {trace:?}"
                );
            }
            assert_eq!(
                trace.iter().filter(|n| n.as_str() == "drop Body").count(),
                usize::from(last != "fail()")
            );
            traces.push(trace);
        }
        assert_eq!(traces[0], traces[1], "inline: {last}, {body}");
        assert_eq!(traces[0], traces[2], "quote: {last}, {body}");
    }
}

#[test]
fn expanded_named_arguments_preserve_preparation_and_parameter_order() {
    use comptime_interpretor::{ErrorKind, Interpreter, Value};
    for fail in [false, true] {
        for mode in ["ordinary", "inline", "quote"] {
            let qualifier = if mode == "quote" { "quote" } else { "inline" };
            let body = if fail { "assumes false;" } else { "" };
            let mut package=compile(&format!("trait Duplicate {{}} trait Retire {{fn drop(*self);}}
                struct Left {{}} struct Right {{}}
                impl Retire for Left {{fn drop(*self) {{}}}} impl Retire for Right {{fn drop(*self) {{}}}}
                fn left()->Left {{Left {{}}}} fn right()->Right {{Right {{}}}}
                {qualifier} fn inspect(implicit left:Left,implicit right:Right) {{{body}}}
                fn entry() {{inspect(.right=right(),.left=left());}}"));
            if mode == "inline" {
                assert!(
                    elaboration::program::inlining::expand(&mut package, &mut 1000000)
                        .unwrap()
                        .expanded
                        > 0
                );
            }
            let executable = source_executable(&package, "entry").unwrap();
            let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_cleanup_schedule(&executable.schedule)
                .unwrap();
            let result = vm.invoke_instance(&executable.entry, vec![]);
            if fail {
                assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
            } else {
                assert_eq!(result.unwrap(), Value::Unit);
            }
            let trace = executed_names(&package, &executable, vm.events())
                .into_iter()
                .filter(|name| {
                    matches!(name.as_str(), "left" | "right" | "drop Left" | "drop Right")
                })
                .collect::<Vec<_>>();
            assert_eq!(
                trace,
                ["right", "left", "drop Right", "drop Left"],
                "{mode}, fail={fail}"
            );
        }
    }
}

