#[test]
fn implicit_cleanup_requires_call_failure_obligations() {
    use comptime_interpretor::Interpreter;
    for invocation in ["helper();", "consume(Held {});"] {
        let package = compile(&format!(
            "trait Duplicate {{}} trait Retire {{fn drop(*self);}}
            struct Caller {{}} struct Held {{}}
            fn caller_retired() {{}}
            impl Retire for Caller {{fn drop(*self) {{caller_retired();}}}}
            impl Retire for Held {{fn drop(*self) {{assumes false;}}}}
            fn helper() {{let held=Held {{}};}}
            fn consume(held:Held) {{}}
            fn entry() {{let caller=Caller {{}};{invocation}}}"
        ));
        let report = cleanup_report(&package, "entry").unwrap();
        assert!(
            report.cleanup_sites.iter().any(|site| site.reason
                == elaboration::verification::moves::CleanupReason::PredicateFailure
                && !site.actions.is_empty()),
            "{invocation}: {report}"
        );
        let executable = source_executable(&package, "entry").unwrap();
        let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
            .unwrap()
            .with_cleanup_schedule(&executable.schedule)
            .unwrap();
        assert!(vm.invoke_instance(&executable.entry, vec![]).is_err());
        // A failure inside Drop is terminal in the current interpreter; this
        // checks the call's conservative obligation, not a new unwinding policy.
    }
}

#[test]
fn void_observation_calls_execute_once_across_inline_boundaries() {
    use comptime_interpretor::{Interpreter, Value};
    for modifier in ["", "inline", "quote"] {
        for body in [
            "tick();if value {return true;}false",
            "if value {tick();return true;}tick();false",
            "let action=tick;action();if value {return true;}false",
            "let unit=tick();if value {return true;}false",
            "value match {true=>tick(),false=>tick()};if value {return true;}false",
            "with_default();if value {return true;}false",
        ] {
            let original=compile(&format!("trait Duplicate {{}} trait Retire {{fn drop(*self);}}
                typealias Action=fn()->.void'builtin;impl Duplicate for Action {{}}
                fn tick() {{}}
                fn with_default(.unit:.void'builtin=tick()) {{}}
                {modifier} fn accept(value:bool)->bool {{{body}}}
                fn entry(input:bool)->bool {{input match {{_ if do {{accept(input)}}=>true,_=>false}}}}
                fn direct(input:bool)->bool {{input match {{_ if do {{tick();input}}=>true,_=>false}}}}
                fn retry(input:bool)->bool {{input match {{
                    _ if do {{tick();false}}=>true,
                    _ if do {{tick();input}}=>true,_=>false
                }}}}"));
            for expanded in [false, true] {
                let mut package = original.clone();
                if expanded {
                    elaboration::program::inlining::expand(&mut package, &mut 1000000).unwrap();
                }
                for (entry, ticks) in [("entry", 1), ("direct", 1), ("retry", 2)] {
                    let executable = source_executable(&package, entry).unwrap_or_else(|error| {
                        panic!("{modifier} expanded={expanded} {body}: {error}")
                    });
                    for input in [false, true] {
                        let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                            .unwrap()
                            .with_cleanup_schedule(&executable.schedule)
                            .unwrap();
                        assert_eq!(
                            vm.invoke_instance(&executable.entry, vec![Value::Bool(input)])
                                .unwrap(),
                            Value::Bool(input)
                        );
                        let names = executed_names(&package, &executable, vm.events());
                        assert_eq!(
                            names.iter().filter(|name| name.as_str() == "tick").count(),
                            ticks,
                            "{modifier} expanded={expanded} {body}"
                        );
                    }
                }
            }
        }
    }
}

