#[test]
fn optional_inline_effect_code_guards_preserve_candidate_order_and_cleanup() {
    use comptime_interpretor::{Interpreter, Value};
    for (pattern, guard) in [
        ("packet", "produce()(packet.flag)"),
        (
            "packet",
            "do {let _ and produce() is action=false;action(packet.flag)}",
        ),
        (
            "packet",
            "(packet.flag match {true=>produce(),false=>produce()})(packet.flag)",
        ),
        ("packet and produce() is action", "action(packet.flag)"),
    ] {
        for resume in [false, true] {
            let selected = if resume {
                "resume packet.flag;false"
            } else {
                "packet.flag"
            };
            let fallback = if resume {
                "resume not packet.flag;false"
            } else {
                "not packet.flag"
            };
            let original=compile(&format!("trait Duplicate {{}} trait Retire {{fn drop(*self);}}
            typealias Action=fn(bool)->bool;impl Duplicate for Action {{}}
            struct Packet {{flag:bool}} struct Scratch {{}} struct Selected {{}} struct Fallback {{}}
            impl Retire for Packet {{fn drop(*self) {{}}}} impl Retire for Scratch {{fn drop(*self) {{}}}}
            impl Retire for Selected {{fn drop(*self) {{}}}} impl Retire for Fallback {{fn drop(*self) {{}}}}
            fn accept(flag:bool)->bool {{flag}}
            fn produce()->Action {{let scratch=Scratch {{}};accept}}
            inline effect inspect(packet:Packet)->bool;
            inline fn request()->#inspect bool {{
                let a=inspect(Packet {{flag:true}})#;
                let b=inspect(Packet {{flag:false}})#;
                let c=inspect(Packet {{flag:true}})#;
                a and b and c
            }}
            fn entry()->bool {{request()# {{
                inspect({pattern}) if {guard}=>do {{let selected=Selected {{}};{selected}}},
                inspect(packet)=>do {{let fallback=Fallback {{}};{fallback}}},
            }}}}"));
            let mut baseline = None;
            for expanded in [false, true] {
                let mut package = original.clone();
                if expanded {
                    let report =
                        elaboration::program::inlining::expand(&mut package, &mut 1000000).unwrap();
                    assert_eq!(report.expanded_handlers, 1, "{guard}: {report}");
                    assert_eq!(report.expanded_requests, 3, "{guard}: {report}");
                }
                let executable = source_executable(&package, "entry")
                    .unwrap_or_else(|error| panic!("{guard}, expanded={expanded}: {error}"));
                let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                    .unwrap()
                    .with_cleanup_schedule(&executable.schedule)
                    .unwrap();
                assert_eq!(
                    vm.invoke_instance(&executable.entry, vec![]).unwrap(),
                    Value::Bool(true)
                );
                let names = executed_names(&package, &executable, vm.events())
                    .into_iter()
                    .filter(|name| name != "request")
                    .collect::<Vec<_>>();
                assert_eq!(
                    names
                        .iter()
                        .filter(|name| name.as_str() == "produce")
                        .count(),
                    3
                );
                assert_eq!(
                    names
                        .iter()
                        .filter(|name| name.starts_with("drop "))
                        .map(String::as_str)
                        .collect::<Vec<_>>(),
                    [
                        "drop Scratch",
                        "drop Selected",
                        "drop Packet",
                        "drop Scratch",
                        "drop Fallback",
                        "drop Packet",
                        "drop Scratch",
                        "drop Selected",
                        "drop Packet"
                    ]
                );
                if let Some(baseline) = &baseline {
                    assert_eq!(&names, baseline, "{guard}");
                } else {
                    baseline = Some(names);
                }
            }
        }
    }
}

