#[test]
fn optional_inline_effect_delivers_owned_closure_capture_once() {
    use comptime_interpretor::{Interpreter, Value};
    let source = "trait Duplicate {} trait Retire {fn drop(*self);}
        struct Ticket {} struct Handler {}
        impl Retire for Ticket {fn drop(*self) {}} impl Retire for Handler {fn drop(*self) {}}
        typealias Callback=%{ticket:Ticket} fn()->Ticket;
        inline effect make()->Callback;
        inline fn subject()->#make Callback {make()#}
        fn entry()->bool {let callback=subject()# {make()=>do {
            let handler=Handler {};let ticket=Ticket {};resume || {return ticket;};
        },};let ticket=callback();true}";
    let mut package = compile(source);
    let report = elaboration::program::inlining::expand(&mut package, &mut 100_000).unwrap();
    assert_eq!(report.expanded_handlers, 1, "{report}");
    let executable = source_executable(&package, "entry").unwrap();
    let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
        .unwrap()
        .with_cleanup_schedule(&executable.schedule)
        .unwrap();
    assert_eq!(
        vm.invoke_instance(&executable.entry, vec![]).unwrap(),
        Value::Bool(true)
    );
    let names = executed_names(&package, &executable, vm.events());
    assert_eq!(
        names
            .iter()
            .filter(|name| name.as_str() == "drop Ticket")
            .count(),
        1
    );
    assert_eq!(
        names
            .iter()
            .filter(|name| name.as_str() == "drop Handler")
            .count(),
        1
    );
    let mut unused = compile(&source.replace("let ticket=callback();true", "true"));
    elaboration::program::inlining::expand(&mut unused, &mut 100_000).unwrap();
    let executable = source_executable(&unused, "entry").unwrap();
    let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
        .unwrap()
        .with_cleanup_schedule(&executable.schedule)
        .unwrap();
    assert_eq!(
        vm.invoke_instance(&executable.entry, vec![]).unwrap(),
        Value::Bool(true)
    );
    assert_eq!(
        executed_names(&unused, &executable, vm.events())
            .iter()
            .filter(|name| name.as_str() == "drop Ticket")
            .count(),
        1
    );
    let mut invalid = compile(&source.replace(
        "let ticket=callback();true",
        "let ticket=callback();let again=callback();true",
    ));
    elaboration::program::inlining::expand(&mut invalid, &mut 100_000).unwrap();
    assert!(
        source_executable(&invalid, "entry").is_err(),
        "owned capture consumed twice"
    );
}

