    use comptime_interpretor::{ErrorKind, Interpreter};
    let package=compile("trait Duplicate {} trait Retire {fn drop(*self);}
        struct Ticket {} struct Held {ready:bool} struct Handler {}
        impl Retire for Ticket {fn drop(*self) {}} impl Retire for Held {fn drop(*self) {}}
        impl Retire for Handler {fn drop(*self) {}}
        typealias Callback=%{ticket:Ticket} fn()->Ticket;
        effect make()->Callback;
        typealias Subject=%{ticket:Ticket,held:Held} fn()->#make bool;
        fn consume(ticket:Ticket) {}
        fn entry()->bool {
            let ticket=Ticket {};let held=Held {ready:true};
            let subject:Subject=|| {consume(ticket);let observed=held.ready;let callback=make()#;let unused=callback();false};
            subject()# {make()=>do {let handler=Handler {};let ticket=Ticket {};assumes false;|| ticket},}
        }");
