#[test]
fn scheduled_handler_copy_enum_capture_invalidates_tags_between_requests() {
    use comptime_interpretor::{Interpreter, Value};
    let package=compile("trait Duplicate {} trait Retire {fn drop(*self);}
        struct Selected {} impl Retire for Selected {fn drop(*self) {}}
        enum Choice {none,some(bool)} impl Duplicate for Choice {}
        effect poll()->bool;
        fn entry()->bool {
            var choice=Choice.none;
            let original=choice;
            let result=do {
                choice=Choice.none;let first=poll()#;
                let selected=choice match {.some(value)=>do {let marker=Selected {};value},.none=>false};
                choice=Choice.none;let second=poll()#;
                first and second and selected
            }# {poll()=>do {choice=Choice.some(true);true},};
            result and (choice match {.some(value)=>do {let marker=Selected {};value},.none=>false})
                and (original match {.none=>true,.some(value)=>false})
        }");
    let executable = source_executable(&package, "entry").unwrap();
    let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
        .unwrap()
        .with_cleanup_schedule(&executable.schedule)
        .unwrap();
    assert_eq!(
        vm.invoke_instance(&executable.entry, vec![]).unwrap(),
        Value::Bool(true)
    );
    let names = executed_names(&package, &executable, vm.events());
    assert_eq!(
        names
            .iter()
            .filter(|name| name.as_str() == "drop Selected")
            .count(),
        2,
        "{names:?}"
    );
}

