#[test]
fn scheduled_handler_copy_enum_capture_rejection_cleans_mutated_value() {
    use comptime_interpretor::{ErrorKind, Interpreter, Value};
    let package=compile("trait Duplicate {} trait Retire {fn drop(*self);}
        enum Choice {none,some(bool)} impl Duplicate for Choice {}
        struct Handler {} struct Caller {}
        impl Retire for Handler {fn drop(*self) {}} impl Retire for Caller {fn drop(*self) {}}
        effect poll()->bool;fn subject()->#poll bool {poll()#}
        fn entry(accept:bool)->bool {
            let held=Caller {};var choice=Choice.none;
            subject()# {poll()=>do {let held=Handler {};choice=Choice.some(true);assumes accept;true},}
        }");
    let executable = source_executable(&package, "entry").unwrap();
    for accept in [true, false] {
        let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
            .unwrap()
            .with_cleanup_schedule(&executable.schedule)
            .unwrap();
        let result = vm.invoke_instance(&executable.entry, vec![Value::Bool(accept)]);
        if accept {
            assert_eq!(result.unwrap(), Value::Bool(true));
        } else {
            assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
        }
        let names = executed_names(&package, &executable, vm.events());
        assert_eq!(
            names
                .iter()
                .filter(|name| name.starts_with("drop "))
                .map(String::as_str)
                .collect::<Vec<_>>(),
            ["drop Handler", "drop Caller"]
        );
    }
}

