#[test]
fn scheduled_computed_data_match_summary_preserves_candidate_calls_and_cleanup() {
    use comptime_interpretor::{Interpreter, Value};
    let package=compile("trait Duplicate {} trait Retire {fn drop(*self);}
        struct Held {flag:bool} impl Retire for Held {fn drop(*self) {}}
        fn check(flag:bool)->bool {flag}
        fn handled(flag:bool)->bool {
            (Held {flag:flag},Held {flag:true}) match {
                ((first,second) and check(first.flag) is (true as ready)) or
                ((second,first) and do {let seen=first.flag;var result=not seen;result=not result;check(result)} is (true as ready))=>ready,
                _=>false
            }
        }
        fn entry(flag:bool)->bool {let held=true;let pointer=held.ref;handled(flag) and pointer.*}");
    let executable = source_executable(&package, "entry").unwrap();
    for flag in [false, true] {
        let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
            .unwrap()
            .with_cleanup_schedule(&executable.schedule)
            .unwrap();
        assert_eq!(
            vm.invoke_instance(&executable.entry, vec![Value::Bool(flag)])
                .unwrap(),
            Value::Bool(true)
        );
        let names = executed_names(&package, &executable, vm.events());
        assert_eq!(
            names.iter().filter(|n| n.as_str() == "check").count(),
            if flag { 1 } else { 2 },
            "{names:?}"
        );
        assert_eq!(
            names.iter().filter(|n| n.as_str() == "drop Held").count(),
            2,
            "{names:?}"
        );
    }
}

