#[test]
fn scheduled_handler_code_observations_preserve_fallback_and_cleanup() {
    use comptime_interpretor::{Interpreter, Value};
    for (guard, defaults) in [
        ("produce()(packet.flag)", 0),
        (
            "do {let _ and produce() is action=false;action(packet.flag)}",
            0,
        ),
        (
            "(packet.flag match {true=>produce(),false=>produce()})(packet.flag)",
            0,
        ),
        ("produce()(with_default(packet.flag))", 3),
        (
            "produce()(with_default(packet.flag,.selected=packet.flag))",
            0,
        ),
    ] {
        let package=compile(&format!("trait Duplicate {{}} trait Retire {{fn drop(*self);}}
            typealias Action=fn(bool)->bool;impl Duplicate for Action {{}}
            struct Packet {{flag:bool}} struct Scratch {{}} struct Inner {{}} struct Outer {{}}
            impl Retire for Packet {{fn drop(*self) {{}}}} impl Retire for Scratch {{fn drop(*self) {{}}}}
            impl Retire for Inner {{fn drop(*self) {{}}}} impl Retire for Outer {{fn drop(*self) {{}}}}
            fn accept(value:bool)->bool {{value}}
            fn produce()->Action {{let held=Scratch {{}};accept}}
            fn default_flag(value:bool)->bool {{value}}
            fn with_default(value:bool,.selected:bool=default_flag(value))->bool {{selected}}
            effect inspect(packet:Packet)->bool;
            fn request()->#inspect bool {{
                let first=inspect(Packet {{flag:true}})#;
                let second=inspect(Packet {{flag:false}})#;
                let third=inspect(Packet {{flag:true}})#;
                first and second and third
            }}
            fn handled()->bool {{
                (request()# {{inspect(packet) if {guard}=>do {{let held=Inner {{}};packet.flag}},}})#
                    {{inspect(packet)=>do {{let held=Outer {{}};not packet.flag}},}}
            }}
            fn entry()->bool {{let held=true;let pointer=held.ref;handled() and pointer.*}}"));
        let executable =
            source_executable(&package, "entry").unwrap_or_else(|error| panic!("{guard}: {error}"));
        let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
            .unwrap()
            .with_cleanup_schedule(&executable.schedule)
            .unwrap();
        assert_eq!(
            vm.invoke_instance(&executable.entry, vec![]).unwrap(),
            Value::Bool(true),
            "{guard}"
        );
        let names = executed_names(&package, &executable, vm.events());
        assert_eq!(
            names
                .iter()
                .filter(|name| name.as_str() == "produce")
                .count(),
            3,
            "{guard}: {names:?}"
        );
        assert_eq!(
            names
                .iter()
                .filter(|name| name.as_str() == "accept")
                .count(),
            3,
            "{guard}: {names:?}"
        );
        assert_eq!(
            names
                .iter()
                .filter(|name| name.as_str() == "default_flag")
                .count(),
            defaults,
            "{guard}: {names:?}"
        );
        assert_eq!(
            names
                .iter()
                .filter(|name| name.starts_with("drop "))
                .map(String::as_str)
                .collect::<Vec<_>>(),
            [
                "drop Scratch",
                "drop Inner",
                "drop Packet",
                "drop Scratch",
                "drop Outer",
                "drop Packet",
                "drop Scratch",
                "drop Inner",
                "drop Packet"
            ],
            "{guard}"
        );
    }
}

