#[test]
fn inline_effect_forwarding_preserves_owned_payload_cleanup() {
    use comptime_interpretor::{Interpreter, Value};
    for finish in ["resume ticket.flag;", "return ticket.flag;"] {
        let original=compile(&format!("trait Duplicate {{}} trait Retire {{fn drop(*self);}}
            struct Ticket {{flag:bool}} struct Producer {{}} struct Middle {{}} struct Sink {{}} struct Caller {{}}
            impl Retire for Ticket {{fn drop(*self) {{}}}}
            impl Retire for Producer {{fn drop(*self) {{}}}}
            impl Retire for Middle {{fn drop(*self) {{}}}}
            impl Retire for Sink {{fn drop(*self) {{}}}}
            impl Retire for Caller {{fn drop(*self) {{}}}}
            inline effect deliver(value:T)->bool where T;
            inline fn produce()->#deliver<Ticket> bool {{let producer=Producer {{}};deliver<Ticket>(Ticket {{flag:true}})#}}
            inline fn forward()->#deliver<Ticket> bool {{produce()# {{deliver<Ticket>(ticket)=>do {{let middle=Middle {{}};deliver<Ticket>(ticket)#}},}}}}
            fn entry()->bool {{let caller=Caller {{}};forward()# {{deliver<Ticket>(ticket)=>do {{let sink=Sink {{}};{finish}}},}}}}"));
        let mut reference = None;
        for expanded in [false, true] {
            let mut package = original.clone();
            if expanded {
                let report =
                    elaboration::program::inlining::expand(&mut package, &mut 1000000).unwrap();
                assert!(report.expanded_handlers >= 2, "{report}");
            }
            let executable = source_executable(&package, "entry").unwrap();
            let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_cleanup_schedule(&executable.schedule)
                .unwrap();
            assert_eq!(
                vm.invoke_instance(&executable.entry, vec![]).unwrap(),
                Value::Bool(true)
            );
            let drops = executed_names(&package, &executable, vm.events())
                .into_iter()
                .filter(|name| name.starts_with("drop "))
                .collect::<Vec<_>>();
            assert_eq!(
                drops,
                vec![
                    "drop Sink",
                    "drop Ticket",
                    "drop Middle",
                    "drop Producer",
                    "drop Caller"
                ],
                "{finish}, expanded={expanded}"
            );
            if let Some(reference) = &reference {
                assert_eq!(&drops, reference);
            } else {
                reference = Some(drops);
            }
        }
    }
}

#[test]
fn inline_effect_pipeline_loop_exits_stop_production_and_unwind_once() {
    use comptime_interpretor::{Interpreter, Value};
    let original=compile("trait Duplicate {} trait Retire {fn drop(*self);}
        struct Ticket {flag:bool} struct Producer {} struct Middle {} struct Sink {} struct Iteration {} struct Caller {}
        impl Retire for Ticket {fn drop(*self) {}}
        impl Retire for Producer {fn drop(*self) {}}
        impl Retire for Middle {fn drop(*self) {}}
        impl Retire for Sink {fn drop(*self) {}}
        impl Retire for Iteration {fn drop(*self) {}}
        impl Retire for Caller {fn drop(*self) {}}
        fn after_request() {} fn after_installation() {}
        inline effect deliver(value:T)->bool where T;
        inline fn produce()->#deliver<Ticket> bool {
            let producer=Producer {};let result=deliver<Ticket>(Ticket {flag:true})#;
            after_request();result
        }
        inline fn forward()->#deliver<Ticket> bool {
            produce()# {deliver<Ticket>(ticket)=>do {let middle=Middle {};deliver<Ticket>(ticket)#},}
        }
        fn entry()->bool {
            let caller=Caller {};var first=true;
            while:consumer true {
                let iteration=Iteration {};
                forward()# {deliver<Ticket>(ticket)=>do {
                    let sink=Sink {};assumes ticket.flag;
                    var local=true;while:inner local {local=false;continue inner;}
                    if first {first=false;continue consumer;}
                    break consumer;
                },};
                after_installation();
            }
            not first
        }");
    for expanded in [false, true] {
        let mut package = original.clone();
        if expanded {
            let report =
                elaboration::program::inlining::expand(&mut package, &mut 1000000).unwrap();
            assert!(report.expanded_handlers >= 2, "{report}");
        }
        let executable = source_executable(&package, "entry").unwrap();
        let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
            .unwrap()
            .with_cleanup_schedule(&executable.schedule)
            .unwrap();
        assert_eq!(
            vm.invoke_instance(&executable.entry, vec![]).unwrap(),
            Value::Bool(true)
        );
        let names = executed_names(&package, &executable, vm.events());
        assert!(
            !names
                .iter()
                .any(|name| name == "after_request" || name == "after_installation"),
            "{names:?}"
        );
        let drops = names
            .into_iter()
            .filter(|name| name.starts_with("drop "))
            .collect::<Vec<_>>();
        let iteration = [
            "drop Sink",
            "drop Ticket",
            "drop Middle",
            "drop Producer",
            "drop Iteration",
        ];
        let expected = iteration
            .iter()
            .chain(iteration.iter())
            .copied()
            .chain(["drop Caller"])
            .collect::<Vec<_>>();
        assert_eq!(drops, expected, "expanded={expanded}");
    }
}

