#[test]
fn generic_inline_producers_deliver_owned_associated_items_once() {
    use comptime_interpretor::{Interpreter, Value};
    for (finish, flag, rejected) in [
        ("resume ticket.flag;", true, false),
        ("return ticket.flag;", true, false),
        ("assumes ticket.flag;resume true;", false, true),
    ] {
        let source=format!("trait Duplicate {{}} trait Retire {{fn drop(*self);}}
            typealias Unit=.void'builtin;
            struct Ticket {{flag:bool}} struct Batch {{item:Ticket}} struct Middle {{}} struct Sink {{}} struct Caller {{}}
            impl Retire for Ticket {{fn drop(*self) {{}}}}
            impl Retire for Batch {{fn drop(*self) {{}}}}
            impl Retire for Middle {{fn drop(*self) {{}}}}
            impl Retire for Sink {{fn drop(*self) {{}}}}
            impl Retire for Caller {{fn drop(*self) {{}}}}
            inline effect deliver(value:T)->bool where T;
            trait Producer {{assoc Item:.Type'builtin;fn produce(self)->#deliver<Item> bool;}}
            impl Producer for Batch {{assoc Item:.Type'builtin=Ticket;
                inline fn produce(self)->#deliver<Ticket> bool {{deliver<Ticket>(self.item)#}}
            }}
            inline fn invoke(value:T)->#deliver<T.as(Producer).Item> bool where T:-Producer {{
                value.produce()# {{deliver<T.as(Producer).Item>(item)=>do {{let middle=Middle {{}};deliver<T.as(Producer).Item>(item)#}},}}
            }}
            fn create()->Batch {{Batch {{item:Ticket {{flag:{flag}}}}}}}
            fn entry()->bool {{let caller=Caller {{}};invoke(create())# {{deliver<Ticket>(ticket)=>do {{let sink=Sink {{}};{finish}}},}}}}");
        let original = compile(&source);
        for expanded in [false, true] {
            let mut package = original.clone();
            if expanded {
                let report =
                    elaboration::program::inlining::expand(&mut package, &mut 1000000).unwrap();
                assert!(report.selected_methods > 0, "{report}");
                assert!(report.expanded_handlers >= 2, "{report}");
            }
            let executable = source_executable(&package, "entry")
                .unwrap_or_else(|error| panic!("{finish}, expanded={expanded}: {error}"));
            let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_cleanup_schedule(&executable.schedule)
                .unwrap();
            let result = vm.invoke_instance(&executable.entry, vec![]);
            if rejected {
                assert_eq!(
                    result.unwrap_err().kind,
                    comptime_interpretor::ErrorKind::ProgramContractRejected
                );
            } else {
                assert_eq!(result.unwrap(), Value::Bool(true));
            }
            let names = executed_names(&package, &executable, vm.events());
            assert_eq!(
                names
                    .iter()
                    .filter(|name| name.as_str() == "create")
                    .count(),
                1
            );
            let drops = names
                .into_iter()
                .filter(|name| name.starts_with("drop "))
                .collect::<Vec<_>>();
            assert_eq!(
                drops,
                [
                    "drop Sink",
                    "drop Ticket",
                    "drop Middle",
                    "drop Batch",
                    "drop Caller"
                ],
                "{finish}, expanded={expanded}"
            );
        }
        // A lexical return makes the second transfer unreachable. Require
        // rejection on the resuming path that actually reaches both requests.
        if finish != "resume ticket.flag;" {
            continue;
        }
        let duplicate=source.replace("deliver<T.as(Producer).Item>(item)#", "do {let ignored=deliver<T.as(Producer).Item>(item)#;deliver<T.as(Producer).Item>(item)#}");
        let original = compile(&duplicate);
        for expanded in [false, true] {
            let mut package = original.clone();
            if expanded {
                elaboration::program::inlining::expand(&mut package, &mut 1000000).unwrap();
            }
            let error = source_executable(&package, "entry")
                .err()
                .unwrap_or_else(|| panic!("duplicate accepted: {finish}, expanded={expanded}"));
            assert!(error.contains("use of unavailable value"), "{error}");
        }
    }
}

#[test]
fn generic_inline_effect_methods_preserve_interface_postconditions() {
    use comptime_interpretor::{ErrorKind, Interpreter, Value};
    for (accepted, own_contract) in [(false, false), (true, false), (false, true), (true, true)] {
        let own = if own_contract {
            " where ensures true"
        } else {
            ""
        };
        let original=compile(&format!("trait Duplicate {{}} trait Retire {{fn drop(*self);}}
            struct Ticket {{flag:bool}} struct Batch {{item:Ticket}} struct Caller {{}}
            impl Retire for Ticket {{fn drop(*self) {{}}}}
            impl Retire for Batch {{fn drop(*self) {{}}}}
            impl Retire for Caller {{fn drop(*self) {{}}}}
            inline effect deliver(value:T)->bool where T;
            trait Producer {{assoc Item:.Type'builtin;fn produce(self)->result:#deliver<Item> bool where ensures result;}}
            impl Producer for Batch {{assoc Item:.Type'builtin=Ticket;
                inline fn produce(self)->#deliver<Ticket> bool{own} {{let result=deliver<Ticket>(self.item)#;assumes result;result}}
            }}
            inline fn invoke(value:T)->#deliver<T.as(Producer).Item> bool where T:-Producer {{value.produce()}}
            fn entry()->bool {{let caller=Caller {{}};invoke(Batch {{item:Ticket {{flag:{accepted}}}}})# {{deliver<Ticket>(ticket)=>ticket.flag,}}}}"));
        for expanded in [false, true] {
            let mut package = original.clone();
            if expanded {
                let report =
                    elaboration::program::inlining::expand(&mut package, &mut 1000000).unwrap();
                assert!(report.selected_methods > 0, "{report}");
                assert_eq!(report.expanded_handlers, 1, "{report}");
            }
            let executable = source_executable(&package, "entry").unwrap();
            let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_cleanup_schedule(&executable.schedule)
                .unwrap();
            let result = vm.invoke_instance(&executable.entry, vec![]);
            if accepted {
                assert_eq!(result.unwrap(), Value::Bool(true));
            } else {
                assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
            }
            assert_eq!(
                vm.events()
                    .iter()
                    .filter(|event| matches!(
                        event,
                        comptime_interpretor::Event::CheckPredicate { .. }
                    ))
                    .count(),
                // Body assumes, inherited implementation postcondition and
                // interface postcondition, plus the explicit implementation
                // clause when present. Invocation boundaries are not deduped.
                if accepted {
                    if own_contract { 4 } else { 3 }
                } else {
                    1
                },
                "accepted={accepted}, own_contract={own_contract}, expanded={expanded}"
            );
            let drops = executed_names(&package, &executable, vm.events())
                .into_iter()
                .filter(|name| name.starts_with("drop "))
                .collect::<Vec<_>>();
            assert_eq!(
                drops,
                ["drop Ticket", "drop Batch", "drop Caller"],
                "accepted={accepted}, own_contract={own_contract}, expanded={expanded}"
            );
        }
    }
}

#[test]
fn newtype_cleanup_executes_nested_representation_destructors_once() {
    use comptime_interpretor::{Event, Interpreter, Storage, Value};
    use elaboration::verification::{
        PlaceId,
        ownership::{Place, Shape, State},
    };
    let package = compile(
        "trait Retire {fn drop(*self);}struct Payload {flag:bool,}impl Retire for Payload {fn drop(*self) {assumes self.flag.*;}}newtype Inner=Payload;impl Retire for Inner {fn drop(*self) {}}newtype Outer=Inner;impl Retire for Outer {fn drop(*self) {}}",
    );
    let wrapper = |name: &str| nir::Term::Nominal {
        declaration: package
            .newtypes
            .iter()
            .find(|item| item.name == name)
            .unwrap()
            .declaration,
        arguments: vec![],
    };
    let inner = wrapper("Inner");
    let outer = wrapper("Outer");
    world(&package, |world, items| {
        let acquired = luna::protocols::acquire_cleanup(
            &package,
            world,
            items,
            &outer,
            Budget::default(),
            &mut 100000,
        )
        .unwrap();
        let receiver = Place {
            root: PlaceId {
                owner: 70,
                local: 1,
            },
            fields: vec![],
        };
        let mut state = State::default();
        state
            .declare(
                receiver.root,
                &Shape::Fields(vec![Shape::Fields(vec![Shape::Fields(vec![Shape::Value])])]),
                true,
                &mut 1000,
            )
            .unwrap();
        let prepared = luna::cleanup::prepare(
            &package,
            world,
            &acquired,
            &state,
            &receiver,
            &[],
            &mut 100000,
            Budget::default(),
        )
        .unwrap();
        let storage = Storage::new(Value::Newtype {
            ty: outer.clone(),
            value: Box::new(Value::Newtype {
                ty: inner.clone(),
                value: Box::new(Value::Record {
                    declaration: package.structs[0].declaration,
                    arguments: vec![],
                    fields: vec![Value::Bool(true)],
                }),
            }),
        });
        let mut interpreter = Interpreter::from_iir(&prepared.graph, Default::default()).unwrap();
        interpreter
            .execute_cleanup(&prepared.program, &storage)
            .unwrap();
        assert_eq!(storage.read().unwrap(), Value::Unit);
        let calls: Vec<_> = interpreter
            .events()
            .iter()
            .filter_map(|event| match event {
                Event::EnterFunction(id) => Some(*id),
                _ => None,
            })
            .collect();
        let subjects = [
            outer.clone(),
            inner.clone(),
            nominal(&package, "Payload", vec![]),
        ];
        let expected: Vec<_> = subjects
            .iter()
            .map(|subject| {
                package
                    .implementations
                    .iter()
                    .find(|implementation| &implementation.subject == subject)
                    .unwrap()
                    .methods[0]
                    .1
            })
            .collect();
        assert_eq!(calls, expected);
        assert_eq!(
            interpreter
                .events()
                .iter()
                .filter(|event| matches!(event, Event::CheckPredicate { passed: true, .. }))
                .count(),
            1
        );
        assert!(
            interpreter
                .execute_cleanup(&prepared.program, &storage)
                .is_err()
        );
    });
}

