#[test]
fn value_indexed_trait_memory_calls_preserve_writes_and_pointer_results() {
    use comptime_interpretor::Value;
    let prefix = "trait Retire {fn drop(*self);} trait Duplicate {}
        trait Access where tag:bool {fn set(*self);fn view(*self)->*bool;}
        struct Item {flag:bool}
        impl Retire for Item {fn drop(*self) {}}
        impl Access<tag> for Item where tag:bool {
            fn set(*self) {self.*.flag = tag;}
            fn view(*self)->*bool {self.*.flag.ref}
        }
        fn consume(value:Item) {}";
    let package = compile(&format!(
        "{prefix} fn entry()->bool {{let source=Item {{flag:false}};
        source.as(Access<true>).set();let pointer=source.as(Access<true>).view();
        let first=pointer.*;source.as(Access<false>).set();first and not pointer.*}}"
    ));
    for name in ["set", "view"] {
        let function = package.functions.iter().find(|f| f.name == name).unwrap();
        for tag in [true, false, true] {
            let summary = elaboration::verification::memory::infer_in_package(
                &package,
                function.declaration,
                &[nir::Term::Bool(tag)],
                &mut 100_000,
            )
            .unwrap();
            assert_eq!(summary.arguments, vec![nir::Term::Bool(tag)]);
            if name == "view" {
                assert!(!summary.result_targets.as_ref().unwrap().is_empty());
            } else {
                assert!(!summary.accesses.is_empty());
            }
        }
    }
    assert_eq!(
        luna::execution::interpret_with_protocols(
            &package,
            "entry",
            "Duplicate",
            "Retire",
            100_000
        )
        .unwrap(),
        Value::Bool(true)
    );
    let package = compile(&format!(
        "{prefix} fn entry()->bool {{let source=Item {{flag:false}};
        let pointer=source.as(Access<true>).view();consume(source);pointer.*}}"
    ));
    let failure = source_executable(&package, "entry").unwrap_err();
    assert!(
        failure.contains("unavailable") || failure.contains("moved"),
        "{failure}"
    );
}

#[test]
fn value_indexed_memory_summaries_specialize_dependent_closures_and_callbacks() {
    use elaboration::verification::memory::{self, CallableInput, CallableResult};
    use nir::{Primitive, Term};
    let package = compile(
        "struct Cell where T, tag:T {value:T}
        impl Cell<T,tag> where T, tag:T {
            fn same(pointer:*T)->*T {pointer}
            fn view(*self)->*T {let pass=|pointer:*T| pointer;pass(self.*.value.ref)}
            fn call(*self,action:fn(*T)->*T)->*T {action(self.*.value.ref)}
            fn closure(*self,action:fn(*T)->*T)->*T {
                let pass=|pointer:*T| action(pointer);pass(self.*.value.ref)
            }
        }",
    );
    let id = |name| {
        package
            .functions
            .iter()
            .find(|f| f.name == name)
            .unwrap()
            .declaration
    };
    for tag in [true, false, true] {
        let arguments = vec![Term::Primitive(Primitive::Bool), Term::Bool(tag)];
        let view =
            memory::infer_in_package(&package, id("view"), &arguments, &mut 100_000).unwrap();
        assert!(!view.result_targets.as_ref().unwrap().is_empty());
        let inputs = std::collections::BTreeMap::from([(
            CallableInput {
                parameter: 1,
                fields: vec![],
            },
            CallableResult::Known(iir::InstanceKey {
                declaration: id("same"),
                arguments: arguments.clone(),
            }),
        )]);
        for method in ["call", "closure"] {
            let summary =
                memory::infer_with_inputs(&package, id(method), &arguments, &inputs, &mut 100_000)
                    .unwrap();
            assert_eq!(summary.result_targets, view.result_targets);
            assert_eq!(summary.arguments, arguments);
        }
    }
    assert!(
        memory::infer_in_package(
            &package,
            id("view"),
            &[Term::Bool(true), Term::Bool(false)],
            &mut 100_000
        )
        .is_err()
    );
    let valid = vec![Term::Primitive(Primitive::Bool), Term::Bool(true)];
    let wrong = std::collections::BTreeMap::from([(
        CallableInput {
            parameter: 1,
            fields: vec![],
        },
        CallableResult::Known(iir::InstanceKey {
            declaration: id("same"),
            arguments: vec![
                Term::Primitive(Primitive::U8),
                Term::Integer(comptime_runtime::Integer::from_i128(7)),
            ],
        }),
    )]);
    assert!(
        memory::infer_with_inputs(&package, id("closure"), &valid, &wrong, &mut 100_000).is_err()
    );
    assert!(memory::infer_in_package(&package, id("view"), &valid, &mut 1).is_err());
    assert!(memory::infer_in_package(&package, id("view"), &valid, &mut 100_000).is_ok());
}

#[test]
fn value_indexed_memory_results_select_only_the_completed_boolean_branch() {
    use elaboration::verification::memory;
    let package = compile(
        "struct Picker where left:bool {
        pub fn pick(a:*bool,b:*bool)->*bool {if left {a} else {b}}
        pub fn dynamic(flag:bool,a:*bool,b:*bool)->*bool {if flag {a} else {b}}
        pub fn closure(a:*bool,b:*bool)->*bool {
            let choose=|x:*bool,y:*bool| if not left or false {y} else {x};choose(a,b)
        }
    }",
    );
    let dynamic = package
        .functions
        .iter()
        .find(|f| f.name == "dynamic")
        .unwrap();
    let summary = memory::infer_in_package(
        &package,
        dynamic.declaration,
        &[nir::Term::Bool(true)],
        &mut 100_000,
    )
    .unwrap();
    assert_eq!(
        summary
            .result_targets
            .unwrap()
            .into_iter()
            .map(|p| p.parameter)
            .collect::<std::collections::BTreeSet<_>>(),
        std::collections::BTreeSet::from([1, 2])
    );
    for name in ["pick", "closure"] {
        let function = package.functions.iter().find(|f| f.name == name).unwrap();
        for left in [true, false, true] {
            let summary = memory::infer_in_package(
                &package,
                function.declaration,
                &[nir::Term::Bool(left)],
                &mut 100_000,
            )
            .unwrap();
            let targets = summary.result_targets.unwrap();
            assert_eq!(targets.len(), 1, "{name} {left}: {targets:?}");
            assert_eq!(
                targets.iter().next().unwrap().parameter,
                if left { 0 } else { 1 }
            );
        }
    }
}

#[test]
fn conditional_drop_loads_filter_payloads_and_preserve_target_types() {
    let prefix="trait Duplicate {}trait Retire {fn drop(*self);}
        typealias u32=.u32'builtin;
        impl Duplicate for bool {}impl Duplicate for u32 {}impl Duplicate for *T where T {}
        enum Choice {none,flag(*bool),count(*u32)}impl Duplicate for Choice {}
        struct Watch {choice:*Choice}
        impl Retire for Watch {fn drop(*self) {let copied=self.choice.*.*;
            let changed=copied match {.none=>true,.flag(p)=>do {p.* = true;p.*},.count(p)=>do {p.* = 7;p.* == 7}};}}
        fn choose(first:bool,a:*bool,b:*u32)->Choice {if first {.flag(a)}else{.count(b)}}";
    for (choice, expected) in [
        ("Choice.none", "not flag and count == 0"),
        ("Choice.flag(flag.ref)", "flag and count == 0"),
        ("Choice.count(count.ref)", "not flag and count == 7"),
        ("choose(true,flag.ref,count.ref)", "flag and count == 0"),
        (
            "choose(false,flag.ref,count.ref)",
            "not flag and count == 7",
        ),
    ] {
        let package = compile(&format!(
            "{prefix}fn run()->bool {{var flag=false;var count:u32=0;
            let choice={choice};do {{let watch=Watch {{choice:choice.ref}};}};{expected}}}"
        ));
        assert_eq!(
            luna::execution::interpret_with_protocols(
                &package,
                "run",
                "Duplicate",
                "Retire",
                1_000_000
            )
            .unwrap_or_else(|error| panic!("{choice}: {error}")),
            comptime_interpretor::Value::Bool(true)
        );
    }
    for owner in [
        "do {let choice=Choice.none;choice.ref}",
        "do {let choice=Choice.flag(flag.ref);choice.ref}",
    ] {
        let package = compile(&format!(
            "{prefix}fn run()->bool {{var flag=false;let pointer={owner};
            do {{let watch=Watch {{choice:pointer}};}};true}}"
        ));
        assert!(
            luna::execution::interpret_with_protocols(
                &package,
                "run",
                "Duplicate",
                "Retire",
                1_000_000
            )
            .is_err(),
            "{owner}"
        );
    }
    for choice in [
        "Choice.flag(do {var flag=false;flag.ref})",
        "Choice.count(do {var count:u32=0;count.ref})",
    ] {
        let package = compile(&format!(
            "{prefix}fn run()->bool {{let choice={choice};
            do {{let watch=Watch {{choice:choice.ref}};}};true}}"
        ));
        assert!(
            luna::execution::interpret_with_protocols(
                &package,
                "run",
                "Duplicate",
                "Retire",
                1_000_000
            )
            .is_err(),
            "{choice}"
        );
    }
}

#[test]
fn conditional_drop_retains_owned_payload_conditions_for_temporaries() {
    let prefix="trait Duplicate {}trait Retire {fn drop(*self);}
        typealias u32=.u32'builtin;
        impl Duplicate for bool {}impl Duplicate for u32 {}impl Duplicate for *T where T {}
        enum Choice {none,flag(*bool),count(*u32)}impl Duplicate for Choice {}
        struct OwnedWatch {choice:Choice}struct Pair {first:bool,second:OwnedWatch}
        impl Retire for OwnedWatch {fn drop(*self) {let copied=self.choice.*;
            let changed=copied match {.none=>true,.flag(p)=>do {p.* = true;p.*},.count(p)=>do {p.* = 7;p.* == 7}};}}
        fn choose(first:bool,a:*bool,b:*u32)->Choice {if first {.flag(a)}else{.count(b)}}
        fn join(a:bool,b:bool)->bool {a and b}";
    for (choice, expected) in [
        ("Choice.none", "not flag and count == 0"),
        ("Choice.flag(flag.ref)", "flag and count == 0"),
        ("Choice.count(count.ref)", "not flag and count == 7"),
        ("choose(true,flag.ref,count.ref)", "flag and count == 0"),
        (
            "choose(false,flag.ref,count.ref)",
            "not flag and count == 7",
        ),
    ] {
        for cleanup in [
            "do {let watch=OwnedWatch {choice:value};};",
            "OwnedWatch {choice:value};",
            "let ignored=join(Pair {first:true,second:OwnedWatch {choice:value}}.first,do {value=Choice.none;true});",
        ] {
            let package = compile(&format!(
                "{prefix}fn run()->bool {{var flag=false;var count:u32=0;var value={choice};{cleanup}{expected}}}"
            ));
            assert_eq!(
                luna::execution::interpret_with_protocols(
                    &package,
                    "run",
                    "Duplicate",
                    "Retire",
                    1_000_000
                )
                .unwrap_or_else(|error| panic!("{choice}, {cleanup}: {error}")),
                comptime_interpretor::Value::Bool(true)
            );
        }
    }
}

#[test]
fn conditional_drop_prepared_arguments_keep_their_original_tag_snapshot() {
    use comptime_interpretor::{ErrorKind, Interpreter};
    let prefix = "trait Duplicate {}trait Retire {fn drop(*self);}
        impl Duplicate for bool {}impl Duplicate for *T where T {}
        enum Choice {none,flag(*bool)}impl Duplicate for Choice {}
        struct OwnedWatch {choice:Choice}
        impl Retire for OwnedWatch {fn drop(*self) {let copied=self.choice.*;
            let changed=copied match {.none=>true,.flag(p)=>do {p.* = true;p.*}};}}
        fn fail(flag:bool)->bool where requires flag == flag {true}
        fn consume(value:OwnedWatch,flag:bool) {}";
    for choice in ["Choice.none", "Choice.flag(flag.ref)"] {
        let mut package = compile(&format!(
            "{prefix}fn entry() {{var flag=false;var value={choice};
            consume(OwnedWatch {{choice:value}},do {{value=Choice.none;fail(false)}});}}"
        ));
        // Inject a runtime rejection after source verification, as in the
        // existing contract-cleanup tests; source false preconditions are rejected.
        package
            .functions
            .iter_mut()
            .find(|function| function.name == "fail")
            .unwrap()
            .preconditions[0]
            .kind = nir::program::ExprKind::Literal(nir::program::Literal::Bool(false));
        let executable = source_executable(&package, "entry").unwrap();
        world(&package, |world, items| {
            let mut items = items.clone();
            let copy = package
                .traits
                .iter()
                .find(|item| item.name == "Duplicate")
                .unwrap()
                .declaration;
            items
                .bind_source_traits(&package, &[(LangItem::Copy, copy)])
                .unwrap();
            let retire = package
                .traits
                .iter()
                .find(|item| item.name == "Retire")
                .unwrap()
                .declaration;
            let pointer_copy = |ty: &nir::Term| {
                elaboration::verification::copy::acquire(
                    &package,
                    world,
                    copy,
                    retire,
                    ty,
                    Budget::default(),
                    &mut 100_000,
                )
                .is_ok()
            };
            let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
                .unwrap()
                .with_pointer_copy_permission(&pointer_copy)
                .with_cleanup_schedule(&executable.schedule)
                .unwrap();
            let failure = vm.invoke_instance(&executable.entry, vec![]).unwrap_err();
            assert_eq!(
                failure.kind,
                ErrorKind::ProgramContractRejected,
                "{failure:?}"
            );
            let names = executed_names(&package, &executable, vm.events());
            assert_eq!(
                names
                    .iter()
                    .filter(|name| name.as_str() == "drop OwnedWatch")
                    .count(),
                1,
                "{choice}: {names:?}"
            );
        });
    }
}

