            let source = format!(
                "{prefix}fn observe(first:*bool,last:*bool,flag:bool)->bool {{{body}}}fn entry()->bool {{let first=false;let last=true;false match {{_ if observe(first.ref,last.ref,{flag})=>true,_=>false}}}}"
            );
