#[test]
fn pointer_pattern_alternatives_retry_observations_and_retire_each_owner_once() {
    use comptime_interpretor::{Interpreter, Value};
    let package = compile(include_str!(
        "../../../development/examples/host-pattern-pointer-cleanup.fl"
    ));
    let executable = source_executable(&package, "run").unwrap();
    let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
        .unwrap()
        .with_cleanup_schedule(&executable.schedule)
        .unwrap();
    assert_eq!(
        vm.invoke_instance(&executable.entry, vec![]).unwrap(),
        Value::Bool(true)
    );
    let names = executed_names(&package, &executable, vm.events());
    assert_eq!(
        names
            .iter()
            .filter(|name| name.as_str() == "inspect")
            .count(),
        6,
        "{names:?}"
    );
    assert_eq!(
        names
            .iter()
            .filter(|name| name.as_str() == "drop Ticket")
            .count(),
        8,
        "{names:?}"
    );
}

#[test]
fn scheduled_handler_restored_owner_cleanup_matches_exit() {
    use comptime_interpretor::{ErrorKind, Interpreter, Value};
    let original = include_str!("../../../development/repros/host-handler-restored-owner.fl");
    for (completion, expected_drops, failure) in [
        ("resume state.flag;", 3, false),
        ("state.flag", 3, false),
        ("return state.flag;", 2, false),
        ("assumes false;resume state.flag;", 2, true),
    ] {
        let package = compile(&original.replace("resume state.flag;", completion));
        let executable = source_executable(&package, "run").unwrap();
        let mut vm = Interpreter::from_iir(&executable.graph, Default::default())
            .unwrap()
            .with_cleanup_schedule(&executable.schedule)
            .unwrap();
        let result = vm.invoke_instance(&executable.entry, vec![]);
        if failure {
            assert_eq!(result.unwrap_err().kind, ErrorKind::ProgramContractRejected);
        } else {
            assert_eq!(result.unwrap(), Value::Bool(true));
        }
        let mut expected = vec!["run".to_owned(), "subject".to_owned()];
        expected.extend(std::iter::repeat_n("drop State".to_owned(), expected_drops));
        assert_eq!(executed_names(&package, &executable, vm.events()), expected);
    }
}

#[test]
fn cleanup_acquisition_lookup_does_not_rescan_unrelated_layouts() {
    use elaboration::verification::{drop::CleanupSession, moves::CleanupPolicy};
    let mut source = String::from(
        "trait Retire {fn drop(*self);}\n\
         struct Wanted {}\n\
         impl Retire for Wanted {fn drop(*self) {}}\n\
         struct Container {payload:?Wanted}\n",
    );
    for index in 0..64 {
        source.push_str(&format!("struct Unrelated{index} {{value:bool}}\n"));
    }
    let package = compile(&source);
    world(&package, |world, _| {
        let protocol = package.traits[0].declaration;
        let wanted = nominal(&package, "Wanted", vec![]);
        let container = nominal(&package, "Container", vec![]);
        let measure = |unrelated: usize| {
            let mut session = CleanupSession::new(&package, world, protocol, Budget::default());
            for index in 0..unrelated {
                session
                    .acquire(
                        &nominal(&package, &format!("Unrelated{index}"), vec![]),
                        &mut 100_000,
                    )
                    .unwrap();
            }
            session.acquire(&container, &mut 100_000).unwrap();
            // Wanted is indexed through both a record field and a variant
            // payload. Finding it must reuse the originally acquired subtree.
            assert!(!session.is_trivial(&wanted, &mut 100_000).unwrap());
            assert!(session.acquire(&wanted, &mut 0).is_err());
            let mut fuel = 100_000;
            for _ in 0..16 {
                session.acquire(&wanted, &mut fuel).unwrap();
            }
            100_000 - fuel
        };
        let small = measure(0);
        let large = measure(64);
        println!("cleanup indexed lookup work: small={small}, large={large}");
        assert_eq!(small, large);
    });
}

#[test]
fn failed_cleanup_indexing_does_not_publish_partial_bindings() {
    use elaboration::verification::{
        PlaceId,
        drop::CleanupSession,
        moves::CleanupPolicy,
        ownership::{Place, Shape, State},
    };
    let package =
        compile("trait Retire {fn drop(*self);}struct Wanted {}struct Container {payload:?Wanted}");
    world(&package, |world, _| {
        let protocol = package.traits[0].declaration;
        let wanted = nominal(&package, "Wanted", vec![]);
        let container = nominal(&package, "Container", vec![]);
        let receiver = Place {
            root: PlaceId {
                owner: 991,
                local: 0,
            },
            fields: vec![],
        };
        let mut state = State::default();
        state
            .declare(receiver.root, &Shape::Fields(vec![]), true, &mut 1000)
            .unwrap();
        let mut saw_index_failure = false;
        for budget in 1..128 {
            let mut session = CleanupSession::new(&package, world, protocol, Budget::default());
            if let Err(error) = session.acquire(&container, &mut { budget }) {
                assert!(
                    session
                        .plan(&wanted, &state, &receiver, &[], &mut 1000)
                        .unwrap_err()
                        .contains("no acquired binding")
                );
                if error.contains("cleanup index budget exhausted") {
                    saw_index_failure = true;
                    session.acquire(&container, &mut 100_000).unwrap();
                    assert!(
                        session
                            .plan(&wanted, &state, &receiver, &[], &mut 1000)
                            .is_ok()
                    );
                    break;
                }
            }
        }
        assert!(
            saw_index_failure,
            "exercise indexing failure after acquisition completes"
        );
    });
}

#[test]
fn cleanup_triviality_reuses_complete_layout_evidence_without_caching_failure() {
    use elaboration::verification::{drop::CleanupSession, moves::CleanupPolicy};
    let mut source = String::from("trait Retire {fn drop(*self);}struct Plain {");
    for index in 0..64 {
        source.push_str(&format!("field{index}:bool,"));
    }
    source.push_str("}struct Custom {plain:Plain}impl Retire for Custom {fn drop(*self) {}}struct Wrapped {payload:?Custom}");
    let package = compile(&source);
    world(&package, |world, _| {
        let protocol = package.traits[0].declaration;
        let mut session = CleanupSession::new(&package, world, protocol, Budget::default());
        for (name, expected) in [("Plain", true), ("Custom", false), ("Wrapped", false)] {
            let ty = nominal(&package, name, vec![]);
            session.acquire(&ty, &mut 100_000).unwrap();
            // Acquiring a layout alone must not publish an unfinished proof.
            assert!(session.is_trivial(&ty, &mut 8).is_err());
            assert!(session.is_trivial(&ty, &mut 8).is_err());
            assert_eq!(session.is_trivial(&ty, &mut 100_000).unwrap(), expected);
            assert!(session.is_trivial(&ty, &mut 0).is_err());
            let mut fuel = 16;
            for _ in 0..16 {
                assert_eq!(session.is_trivial(&ty, &mut fuel).unwrap(), expected);
            }
            assert_eq!(fuel, 0, "charge the nominal key on every hit");
        }
    });
}
